INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-CRIM-002-EXPANDED', '400', 'Detention orders shall be enforced by placing the persons to be detained in remand centres. Convicted persons shall be incarcerated in prisons, where the judgements against them shall be enforced.', 'en', 'Code of Criminal Procedure (Expanded), Article 400', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '401', 'Remand centres and prisons shall be established and organized pursuant to a decree issued by the Council of Ministers.', 'en', 'Code of Criminal Procedure (Expanded), Article 401', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '402', 'The Appeal Court Prosecutor, the Financial Prosecutor, the Investigating Judge and the Single Criminal Judge shall examine the situation of persons held in remand centres and prisons in their respective areas of jurisdiction once a month. – Each of the aforementioned persons may order those responsible for remand centres and prisons in their respective areas of jurisdiction to undertake such measures as are required by the investigation and the trial.', 'en', 'Code of Criminal Procedure (Expanded), Article 402', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '403', 'Where the Appeal Court Prosecutor, the Financial Prosecutor or the Single Criminal Judge obtains knowledge, within his area of jurisdiction, of the unlawful detention of any person, he shall release the person after verifying whether the detention is unlawful. If any one of them ascertains that there is a lawful ground for detention, he shall send the detainee forthwith to the competent judicial authority and prepare a record of the fact. If any of them fails to comply with the foregoing provisions, he shall be subject to disciplinary action.', 'en', 'Code of Criminal Procedure (Expanded), Article 403', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '404', 'Final criminal judgements delivered by Criminal and Appeal Courts and the Court of Cassation shall be enforced by the Public Prosecutor of the Court that rendered the judgement. The Single Criminal Judge shall enforce the judgements he delivers. Enforcement of the provisions of judgements shall be ensured by means of written instructions to the Internal Security Forces.', 'en', 'Code of Criminal Procedure (Expanded), Article 404', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '405', 'The provisions of Articles 35 to 65 inclusive and Articles 112 to 117 inclusive of the Criminal Code shall be applicable to the enforcement of criminal judgements.', 'en', 'Code of Criminal Procedure (Expanded), Article 405', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '406', 'The day on which the enforcement begins shall be deducted from the term of the sentence. The convicted person shall be released on the day on which the term of the sentence ends. – Enforcement of a custodial sentence of twenty-four hours ends on the day after the beginning of enforcement. – The period of enforcement of a custodial sentence or a sentence restricting liberty shall begin on the date of arrest of the convicted person pursuant to the judgement delivered against him; any period spent in pre-trial detention shall be deducted therefrom.', 'en', 'Code of Criminal Procedure (Expanded), Article 406', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '407', 'If the accused or defendant is acquitted of the offence for which he was placed in pre-trial detention, the period spent in detention shall be deducted from the sentence for any other offence he may have committed before or during his detention. English version (STL Draft Official Translation of Arabic) Version 1.0 92', 'en', 'Code of Criminal Procedure (Expanded), Article 407', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '408', 'In the case of multiple custodial sentences or sentences restricting liberty imposed against a defendant or accused, the period of detention shall be deducted first from the lightest sentence.', 'en', 'Code of Criminal Procedure (Expanded), Article 408', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '409', 'If a pregnant woman is convicted, enforcement of the sentence shall be deferred until ten weeks after delivery of her child.', 'en', 'Code of Criminal Procedure (Expanded), Article 409', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '410', 'If a custodial sentence or a sentence restricting liberty is imposed on a person suffering from a life-threatening illness, the sentence may be enforced in the prison hospital.', 'en', 'Code of Criminal Procedure (Expanded), Article 410', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '411', 'If a custodial sentence or a sentence restricting liberty is imposed on a person suffering from a nervous breakdown or serious mental illness, the Public Prosecutor’s Office may order that he be placed in a mental hospital. The period spent in the hospital shall be deducted from the sentence imposed. If the illness persists, the legal provisions applicable to mentally ill persons shall be applied to him.', 'en', 'Code of Criminal Procedure (Expanded), Article 411', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '412', 'A detained person shall be released on delivery of a judgement of acquittal or exemption from punishment; imposition of a non-custodial sentence; imposition of a suspended sentence; or where the detainee has already served the period of the sentence in pre-trial detention.', 'en', 'Code of Criminal Procedure (Expanded), Article 412', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '413', 'If the convicted person is sentenced to pay personal damages, judicial costs and a fine, and his funds are insufficient to meet all those payments, the sentence shall be enforced on the basis of the following priorities: (a) Personal damages; (b) Judicial costs; (c) The fine.', 'en', 'Code of Criminal Procedure (Expanded), Article 413', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '414', 'The personal damages awarded pursuant to the civil party’s claim and the advance in respect of judicial fees and costs shall be enforced pursuant to the provisions of the Code of Civil Procedure.', 'en', 'Code of Criminal Procedure (Expanded), Article 414', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '415', 'A person sentenced to pay judicial costs shall pay them to the Treasury within ten days of the date of receiving notice to pay following the final judgement. If he fails to pay that sum, the Public Prosecutor shall order his imprisonment for a period of twenty-four hours for every 10,000 Lebanese pounds owed. The period of imprisonment may not exceed six months. The convicted person may not be imprisoned for failure to pay judicial costs if he was a minor when the offence was committed. If the period spent in detention exceeds the term of imprisonment, a sum shall be deducted from the fine and judicial costs imposed in accordance with the rate set out above.', 'en', 'Code of Criminal Procedure (Expanded), Article 415', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '416', 'The rule governing apportionment set out in Article 53 of the Criminal Code shall be applicable to the judicial costs.', 'en', 'Code of Criminal Procedure (Expanded), Article 416', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '417', 'If the convicted person serves a period of imprisonment in lieu of the fine and judicial costs, his debt to the Treasury shall be cancelled.', 'en', 'Code of Criminal Procedure (Expanded), Article 417', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '418', 'If a convicted person who is imprisoned for failure to pay the fine and judicial costs expresses the wish, while in prison, to discharge his debt to the State, the Public Prosecutor or his deputy shall order that he be released from prison and produced before him to pay the sums due, following deduction of the sum equivalent to the period spent in prison. English version (STL Draft Official Translation of Arabic) Version 1.0 93 If the convicted person pays the entire sum required on arrest, he shall be released forthwith and the order to imprison him for failure to pay the fine and judicial costs shall be annulled.', 'en', 'Code of Criminal Procedure (Expanded), Article 418', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '419', 'In the event of the death, flight or incapacity of the convicted person, the judicial costs and the fine shall be collected in accordance with the procedure for the collection of funds by the Ministry of Finance.', 'en', 'Code of Criminal Procedure (Expanded), Article 419', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '420', 'A death penalty shall be enforced only after consultation of the Pardon Commission and with the consent of the President of the Republic. The judgement shall be enforced pursuant to a decree specifying the place and means of execution. A death penalty shall not be executed on Sundays or Fridays, or on national or religious holidays. A death penalty shall not be enforced against a pregnant woman until ten weeks after she has given birth.', 'en', 'Code of Criminal Procedure (Expanded), Article 420', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '421', 'The death penalty shall be executed in the presence of the following persons: (a) The President of the Court that delivered the judgement. If he is unable to attend, the First President of the Court of Cassation shall appoint a Judge to replace him; (b) The Public Prosecutor at the court that delivered the judgement, or one of his deputies; (c) A Judge of the civil court of first instance which has jurisdiction in the place of execution; (d) The clerk of the court that delivered the judgement; (e) Counsel for the convicted person; (f) A member of the clergy of the religious denomination to which the convicted person belongs; (g) The prison governor; (h) The Beirut Judicial Police Commissioner or his deputy, or the Gendarmerie commander responsible for the place of execution or his deputy; (i) The prison doctor or the forensic physician of the region.', 'en', 'Code of Criminal Procedure (Expanded), Article 421', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '422', 'The civil Judge referred to in subparagraph (c) of the preceding article shall ask the convicted person whether he wishes to say anything or to make a statement before execution of the judgement. This shall be noted in a special record signed by him and his clerk.', 'en', 'Code of Criminal Procedure (Expanded), Article 422', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '423', 'The clerk of the court that delivered the judgement shall draw up a record of the execution of the death penalty and it shall be signed by the persons mentioned in subparagraphs (a), (b) and (d) of Article 421 of this Code at the place of execution. A copy of the record shall be displayed for twenty-four hours at the place of execution. The clerk shall attach a copy of the record of the execution of the judgement to the original copy of the judgement deposited with the registry of the court.', 'en', 'Code of Criminal Procedure (Expanded), Article 423', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '424', 'It is prohibited to publish any statement regarding execution of the death penalty in the newspapers apart from the record mentioned in the preceding article. Anyone who breaches this prohibition shall be liable to the penalty provided for under Article 420 of the Criminal Code. English version (STL Draft Official Translation of Arabic) Version 1.0 94 Part XII Procedures for the enforcement of criminal judgements', 'en', 'Code of Criminal Procedure (Expanded), Article 424', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '425', 'Once a court delivers its judgement, it is no longer seized of the case.', 'en', 'Code of Criminal Procedure (Expanded), Article 425', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '426', 'If a purely factual error, or one of a clerical or computational nature, occurs in the judgement or ruling delivered by a judicial authority, the authority may correct the error of its own motion or pursuant to a request from one of the parties to the case. The decision to correct shall be taken in chambers and the correction shall be recorded in the margin of the judgement or ruling.', 'en', 'Code of Criminal Procedure (Expanded), Article 426', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '427', 'Any request for interpretation in relation to a judgement shall fall under the jurisdiction of the court that delivered it. It shall rule thereon after consulting the Public Prosecutor’s Office. English version (STL Draft Official Translation of Arabic) Version 1.0 95 Part XIII Transitional provisions', 'en', 'Code of Criminal Procedure (Expanded), Article 427', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '428', 'The Code of Criminal Procedure Act promulgated on 18 September 1948 and its amendments are hereby revoked and all legal provisions and texts that are inconsistent or in conflict with this Code are also revoked.', 'en', 'Code of Criminal Procedure (Expanded), Article 428', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '429', 'This Code shall enter into effect three months after its publication in the Official Gazette. 2 2 This Code was published in issue No. 38 of the Official Gazette of 7 August 2001. English version (STL Draft Official Translation of Arabic) Version 1.0 96 Table of articles Code of Criminal Procedure Articles General provisions 1–4 Public prosecutions and civil actions 5 – 10 Part I: The Public Prosecution Service 11 – 12 Chapter I: Duties of the Public Prosecutor at the Court of Cassation 13 – 17 Chapter II: Duties of the Financial Prosecutor’s Office 18 – 23 Chapter III: Duties of the Public Prosecutor’s Office at the Appeal Court and procedures in the case of an offence discovered at the time of its commission or immediately afterwards v Section I: Duties of the Public Prosecutor’s Office at the Appeal Court 24 – 28 v Section II: Procedures to be followed by the Public Prosecutor’s Office 29 – 37 in the case of an offence discovered at the time of its commission or immediately afterwards Part II: The Judicial Police Chapter I: Members of the Judicial Police 38 – 39 Chapter II: Measures to be taken by the Judicial Police 40 in connection with offences discovered at the time of their commission or immediately afterwards and those which do not fall into this category v Section I: Measures to be taken by the Judicial Police in connection 41 – 46 with offences discovered at the time of their commission or immediately afterwards v Section II: Measures to be taken by the Judicial Police in connection 47 – 50 with offences not discovered at the time of their commission or immediately afterwards Part III: Investigating Judges and their duties Chapter I: Organization of the Investigation Departments 51 – 54 Chapter II: Duties of the Investigating Judge in the case of offences 55 – 58 discovered at the time of their commission or immediately afterwards Chapter III: Duties of the Investigating Judge in the case of offences not discovered at the time of their commi', 'en', 'Code of Criminal Procedure (Expanded), Article 429', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', NULL, 'Full article-level text of the Lebanese Code of Criminal Procedure (Law No. 328/2001). Governs criminal investigations, prosecution, trial procedures, evidence, detention, appeals, and execution of criminal judgments.', 'en', 'Code of Criminal Procedure (Expanded) — Historical Context', 'Historical context and overview', 'Criminal Law'),
  ('LB-LAB-001-EXPANDED', '1', 'Scope of Application: The present Code shall apply to all employers and employees in Lebanon, subject to the exceptions provided herein. It governs the relations between employers and employees and defines their respective rights and obligations arising from employment contracts.', 'en', 'Code of Labour (1946) - Expanded, Article 1', 'Scope of Application', 'labor'),
  ('LB-LAB-001-EXPANDED', '2', 'Definition of Employer: An employer is any person, natural or juridical, who in an industrial, trading, or agricultural enterprise employs a worker in some capacity under a contract of employment, whether written or verbal.', 'en', 'Code of Labour (1946) - Expanded, Article 2', 'Definition of Employer', 'labor'),
  ('LB-LAB-001-EXPANDED', '3', 'Definition of Employee: An employee is any person who undertakes, in return for remuneration, to work under the direction and supervision of another person, whether the contract is for a fixed or indefinite period.', 'en', 'Code of Labour (1946) - Expanded, Article 3', 'Definition of Employee', 'labor'),
  ('LB-LAB-001-EXPANDED', '4', 'Exclusions from Application: The following are excluded from the scope of this Code: domestic servants and persons employed in family enterprises where only members of the family are employed. Agricultural workers are governed by special provisions.', 'en', 'Code of Labour (1946) - Expanded, Article 4', 'Exclusions from Application', 'labor'),
  ('LB-LAB-001-EXPANDED', '5', 'Written and Oral Contracts: The contract of labor can be either oral or written; if written, it must be in Arabic. It may however be translated into a foreign language if one of the parties does not understand Arabic.', 'en', 'Code of Labour (1946) - Expanded, Article 5', 'Written and Oral Contracts', 'labor'),
  ('LB-LAB-001-EXPANDED', '6', 'Types of Employment Contracts: Employment contracts may be for a determined or undetermined duration. A contract for a determined duration must specify the period or the completion of a specific task. If the parties continue to perform after the expiry of a fixed-term contract, it shall be deemed renewed for an indefinite period.', 'en', 'Code of Labour (1946) - Expanded, Article 6', 'Types of Employment Contracts', 'labor'),
  ('LB-LAB-001-EXPANDED', '7', 'Trial Period: The employment contract may provide for a trial period not exceeding three months. During this period, either party may terminate the contract without notice or indemnity. If the employee is retained beyond the trial period, the duration of the trial shall be counted as part of the service period.', 'en', 'Code of Labour (1946) - Expanded, Article 7', 'Trial Period', 'labor'),
  ('LB-LAB-001-EXPANDED', '8', 'Establishments Subject to the Code: This Code applies to industrial, commercial, and agricultural establishments, as well as to enterprises providing services, public utility companies, liberal professions, associations, and other entities employing workers under conditions of subordination.', 'en', 'Code of Labour (1946) - Expanded, Article 8', 'Establishments Subject to the Code', 'labor'),
  ('LB-LAB-001-EXPANDED', '31', 'Maximum Working Hours: The maximum working hours shall be 48 hours per week. The employer shall organize working hours within this limit. Working hours may be distributed over six days or reduced to five days with corresponding longer daily hours, provided the daily maximum does not exceed the limits set by regulation.', 'en', 'Code of Labour (1946) - Expanded, Article 31', 'Maximum Working Hours', 'labor'),
  ('LB-LAB-001-EXPANDED', '32', 'Overtime Compensation: Work performed beyond the normal working hours shall be compensated at a rate of at least 50% above the normal wage rate. Work performed on weekly rest days or public holidays shall be compensated at double the normal rate.', 'en', 'Code of Labour (1946) - Expanded, Article 32', 'Overtime Compensation', 'labor'),
  ('LB-LAB-001-EXPANDED', '33', 'Night Work Restrictions: Women and minors under eighteen years of age shall not be employed in industrial work between 7:00 PM and 7:00 AM, subject to exceptions provided by decree. Night work for adult male workers shall be compensated at a higher rate.', 'en', 'Code of Labour (1946) - Expanded, Article 33', 'Night Work Restrictions', 'labor'),
  ('LB-LAB-001-EXPANDED', '34', 'Weekly Rest: Every employee is entitled to a weekly rest period of at least 36 consecutive hours, which shall normally include Sunday. The employer may fix the weekly rest day on a day other than Sunday for certain categories of work, provided the minimum rest period is observed.', 'en', 'Code of Labour (1946) - Expanded, Article 34', 'Weekly Rest', 'labor'),
  ('LB-LAB-001-EXPANDED', '35', 'Public Holidays: Employees are entitled to paid leave on official public holidays as determined by the government. Work performed on public holidays shall be compensated at double the normal rate.', 'en', 'Code of Labour (1946) - Expanded, Article 35', 'Public Holidays', 'labor'),
  ('LB-LAB-001-EXPANDED', '44', 'Minimum Wage: The minimum wage shall be fixed by decree of the Council of Ministers, taking into account the cost of living, the economic situation, and the needs of the worker and his family. The salary should not be less than the average of the official minimum salary. The minimum wage as fixed by the Government is 675,000 LBP (subject to periodic revision).', 'en', 'Code of Labour (1946) - Expanded, Article 44', 'Minimum Wage', 'labor'),
  ('LB-LAB-001-EXPANDED', '45', 'Payment of Wages: Wages shall be paid at regular intervals not exceeding one month for monthly employees and one week for daily or piece-rate workers. Payment shall be made in the national currency at the workplace or through a bank transfer. Wages must be paid before any housing allowance that forms part of the remuneration.', 'en', 'Code of Labour (1946) - Expanded, Article 45', 'Payment of Wages', 'labor'),
  ('LB-LAB-001-EXPANDED', '46', 'Wage Deductions: No deductions shall be made from an employee''s wages except those provided by law, such as social security contributions, income tax, and amounts ordered by a court. Fines imposed by the employer shall not exceed five days'' wages per month.', 'en', 'Code of Labour (1946) - Expanded, Article 46', 'Wage Deductions', 'labor'),
  ('LB-LAB-001-EXPANDED', '47', 'Equal Pay: Women shall receive equal pay with men for equal work of the same nature and quality performed under the same conditions.', 'en', 'Code of Labour (1946) - Expanded, Article 47', 'Equal Pay', 'labor'),
  ('LB-LAB-001-EXPANDED', '38', 'Annual Leave: Every employee has the right, every year, to take fifteen days of paid annual leave if one year has passed from the date of the conclusion of the employment contract. Employers may choose the date for such leaves according to work circumstances. The employer cannot dismiss the employee or send him a warning or a notice during his annual leave.', 'en', 'Code of Labour (1946) - Expanded, Article 38', 'Annual Leave', 'labor'),
  ('LB-LAB-001-EXPANDED', '39', 'Sick Leave: An employee who is unable to work due to illness or injury not related to employment shall be entitled to sick leave based on a medical report. The employer cannot dismiss or warn the employee during sick leave. The duration and compensation for sick leave is: half a month with full salary and half a month with half salary for employees with 3 months to 2 years of service; one month with full salary and one month with half salary for 2 to 4 years of service; one month and a half with full salary and one month and a half with half salary for 4 to 6 years of service; two months with full salary and two months with half salary for 6 to 10 years of service.', 'en', 'Code of Labour (1946) - Expanded, Article 39', 'Sick Leave', 'labor');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-LAB-001-EXPANDED', '40', 'Maternity Leave: A female employee is entitled to seven weeks of maternity leave with full pay, which may be taken before or after delivery. The employer shall not dismiss a female employee during her maternity leave or because of pregnancy. A nursing mother is entitled to one hour per day for nursing during the first year after birth.', 'en', 'Code of Labour (1946) - Expanded, Article 40', 'Maternity Leave', 'labor'),
  ('LB-LAB-001-EXPANDED', '41', 'Bereavement Leave: An employee is entitled to two days of paid leave in case of the death of a family member (father, mother, children, or grandparents).', 'en', 'Code of Labour (1946) - Expanded, Article 41', 'Bereavement Leave', 'labor'),
  ('LB-LAB-001-EXPANDED', '42', 'Leave During Notice Period: The employee has the right to leave work for one hour per day to search for another job during the notice period if any resignation or termination occurs.', 'en', 'Code of Labour (1946) - Expanded, Article 42', 'Leave During Notice Period', 'labor'),
  ('LB-LAB-001-EXPANDED', '48', 'Employer''s Obligation to Pay Salary: The employer must pay salary weekly or monthly. Payment may be in cash or in kind. The employer must pay the employee their basic wage before any housing allowance that forms part of their remuneration.', 'en', 'Code of Labour (1946) - Expanded, Article 48', 'Employer''s Obligation to Pay Salary', 'labor'),
  ('LB-LAB-001-EXPANDED', '49', 'Healthy and Safe Workplace: The employer must provide a healthy workplace with no hazardous environment and safe equipment. The employer shall take all necessary precautions to protect the lives and health of employees.', 'en', 'Code of Labour (1946) - Expanded, Article 49', 'Healthy and Safe Workplace', 'labor'),
  ('LB-LAB-001-EXPANDED', '50', 'Dignity and Respect: The employer must treat the employee with dignity. No insult or harassment shall be directed at employees. The employer shall respect the personal dignity and freedom of the employee.', 'en', 'Code of Labour (1946) - Expanded, Article 50', 'Dignity and Respect', 'labor'),
  ('LB-LAB-001-EXPANDED', '51', 'Provision of Work and Tools: The employer must allow the employee to do their job by providing access to the premises and supplying the pertinent tools needed to fulfill their tasks.', 'en', 'Code of Labour (1946) - Expanded, Article 51', 'Provision of Work and Tools', 'labor'),
  ('LB-LAB-001-EXPANDED', '52', 'Internal Work Policy: An employer who has fifteen employees or more must establish an internal work policy (règlement intérieur) setting out the rules of discipline, working hours, leaves, and other working conditions. This policy must be approved by the Ministry of Labour.', 'en', 'Code of Labour (1946) - Expanded, Article 52', 'Internal Work Policy', 'labor'),
  ('LB-LAB-001-EXPANDED', '53', 'Performance of Work: The employee must perform the work as agreed in the employment contract and act as a prudent administrator in carrying out assigned duties.', 'en', 'Code of Labour (1946) - Expanded, Article 53', 'Performance of Work', 'labor'),
  ('LB-LAB-001-EXPANDED', '54', 'Following Instructions: The employee must follow the orders and instructions of the employer and work under the employer''s supervision and direction.', 'en', 'Code of Labour (1946) - Expanded, Article 54', 'Following Instructions', 'labor'),
  ('LB-LAB-001-EXPANDED', '55', 'Non-Competition: The employee must refrain from competition with the employer during and after employment, subject to limitations of time and distance as may be agreed in the contract or required by law.', 'en', 'Code of Labour (1946) - Expanded, Article 55', 'Non-Competition', 'labor'),
  ('LB-LAB-001-EXPANDED', '50-A', 'Termination by Mutual Consent: The employment contract may be terminated by the mutual consent of both parties. In this case, both parties decide to put an end to the employment contract by agreement.', 'en', 'Code of Labour (1946) - Expanded, Article 50-A', 'Termination by Mutual Consent', 'labor'),
  ('LB-LAB-001-EXPANDED', '50-B', 'Termination by Force Majeure: Any strong event (force majeure) which might happen to the employer, to the employee, or to the establishment, such as the reduction in the size of the establishment, substituting a line of production with another, or the permanent cessation of work, could lead to the termination of the employment contract.', 'en', 'Code of Labour (1946) - Expanded, Article 50-B', 'Termination by Force Majeure', 'labor'),
  ('LB-LAB-001-EXPANDED', '50-C', 'Termination by Employer Without Indemnity: The employer may terminate the employment contract without indemnity in the following cases: (a) If the employee has assumed a nationality that is not his own; (b) If the period of work was set as a trial and the employer refused the employee within the three-month time limit; (c) If the employee commits or causes any damage to the employer, provided the employer documents this in writing and submits it to the Labour Ministry within three days; (d) If the employee has been absent, with no legal excuse, for more than fifteen days in one year, or for seven consecutive days; (e) If the employee was imprisoned for one year or more for a felony or misdemeanor at or through work; (f) If the employee attacked the employer or the manager at work.', 'en', 'Code of Labour (1946) - Expanded, Article 50-C', 'Termination by Employer Without Indemnity', 'labor'),
  ('LB-LAB-001-EXPANDED', '50-D', 'Termination by Employee: The employee has the right to leave work before the end of the employment contract in the following cases: (a) If the employer or his representative misleads the employee about the conditions of work, within thirty days of starting work; (b) If the employer fails to execute his obligations; (c) If the employer commits an unethical act against the employee or a member of his family; (d) If the employer or his representative commits a violent act against the employee.', 'en', 'Code of Labour (1946) - Expanded, Article 50-D', 'Termination by Employee', 'labor'),
  ('LB-LAB-001-EXPANDED', '50-E', 'Abusive Dismissal: A dismissal is considered abusive (without just reason) when it is: (a) Not related to the quality of work; (b) Due to union membership; (c) Due to running for or being elected to union office; (d) Due to submitting a complaint to the Labour Ministry regarding implementation of labor law or filing a complaint against the employer; (e) Due to the employee exercising personal freedoms within the law. The damaged party may claim before the Labor Council within one month from knowledge of the dismissal and may use all kinds of proof. The Labor Council must take its decision within three months.', 'en', 'Code of Labour (1946) - Expanded, Article 50-E', 'Abusive Dismissal', 'labor'),
  ('LB-LAB-001-EXPANDED', '50-F', 'End-of-Service Indemnity: The employer must pay the dismissed employee a remuneration equivalent to the salary of one month for every year worked, and the salary of half a month if the period of work was less than one year. An employee who has reached the age of 60 or who has completed 25 years of service at the same job may request dismissal and benefit from the leave indemnity.', 'en', 'Code of Labour (1946) - Expanded, Article 50-F', 'End-of-Service Indemnity', 'labor'),
  ('LB-LAB-001-EXPANDED', '50-G', 'Warning and Infringement Procedure: If the employee, despite a warning, has committed three infringements against the internal regulations within one year, the employer may terminate the contract without indemnity. The employer must document each infringement in writing and submit it to the Labour Ministry within three days from the date of becoming aware of the infringement.', 'en', 'Code of Labour (1946) - Expanded, Article 50-G', 'Warning and Infringement Procedure', 'labor'),
  ('LB-LAB-001-EXPANDED', '77', 'Labor Councils (Judicial Competency): In each district (Mouhafaza), there is one or more Labor Council which treats disputes arising between employers and employees. The Labor Council is composed of: (1) A judge from the 11th degree and above as president; (2) Two members: one employee representative and one employer representative (with two alternates for absences); (3) A Government Commissioner of the 3rd degree.', 'en', 'Code of Labour (1946) - Expanded, Article 77', 'Labor Councils (Judicial Competency)', 'labor'),
  ('LB-LAB-001-EXPANDED', '78', 'Labor Council Procedures: The Labor Council shall attempt to reconcile the parties before proceeding to adjudicate the dispute. If reconciliation fails, the Council shall render a decision. For abusive dismissal claims, the Council must take its decision within three months.', 'en', 'Code of Labour (1946) - Expanded, Article 78', 'Labor Council Procedures', 'labor'),
  ('LB-LAB-001-EXPANDED', '22', 'Prohibition of Child Labour: Children under the age of 14 years shall not be employed in any work. Children between 14 and 18 years may be employed only in light work that is not harmful to their health, growth, or education, and only with the authorization of the Ministry of Labour.', 'en', 'Code of Labour (1946) - Expanded, Article 22', 'Prohibition of Child Labour', 'labor'),
  ('LB-LAB-001-EXPANDED', '23', 'Restrictions on Women''s Employment: Women shall not be employed in work that is dangerous, unhealthy, or morally harmful as defined by decree. Pregnant women shall not be required to perform work that may endanger their health or that of the child.', 'en', 'Code of Labour (1946) - Expanded, Article 23', 'Restrictions on Women''s Employment', 'labor'),
  ('LB-LAB-001-EXPANDED', '24', 'Equal Treatment: Employers shall ensure equal treatment of employees regardless of sex, origin, or belief in matters of hiring, working conditions, promotion, wages, and termination.', 'en', 'Code of Labour (1946) - Expanded, Article 24', 'Equal Treatment', 'labor'),
  ('LB-LAB-001-EXPANDED', '83', 'Trade Unions: Workers and employers have the right to form and join trade unions for the defense of their professional interests. Trade unions must be registered with the Ministry of Labour and must have at least 15 members.', 'en', 'Code of Labour (1946) - Expanded, Article 83', 'Trade Unions', 'labor'),
  ('LB-LAB-001-EXPANDED', '84', 'Collective Bargaining: Employers and trade unions may negotiate collective labor agreements establishing conditions of employment that are more favorable than those provided by law. Collective agreements must be in writing and registered with the Ministry of Labour.', 'en', 'Code of Labour (1946) - Expanded, Article 84', 'Collective Bargaining', 'labor'),
  ('LB-LAB-001-EXPANDED', '85', 'Right to Strike: Workers have the right to strike as a means of defending their professional interests, provided that conciliation and mediation procedures have been exhausted. Strikes must be peaceful and must not involve violence or occupation of premises.', 'en', 'Code of Labour (1946) - Expanded, Article 85', 'Right to Strike', 'labor'),
  ('LB-LAB-001-EXPANDED', '86', 'Lock-out: Employers may resort to lock-out only after conciliation and mediation procedures have been exhausted. Lock-out must comply with the provisions of the Code of Collective Labor Agreements.', 'en', 'Code of Labour (1946) - Expanded, Article 86', 'Lock-out', 'labor'),
  ('LB-LAB-001-EXPANDED', '87', 'Work-Related Injuries: Employers are liable for injuries and occupational diseases suffered by employees in the course of or because of their work. Compensation for work-related injuries is governed by the Code of Occupational Injuries of 1983.', 'en', 'Code of Labour (1946) - Expanded, Article 87', 'Work-Related Injuries', 'labor'),
  ('LB-LAB-001-EXPANDED', '88', 'Social Security Contributions: Employers and employees are required to contribute to the National Social Security Fund (NSSF) as provided by the Code of Social Security of 1963. The NSSF provides benefits for sickness, maternity, family allowances, and end-of-service indemnity.', 'en', 'Code of Labour (1946) - Expanded, Article 88', 'Social Security Contributions', 'labor'),
  ('LB-LAB-001-EXPANDED', '9', 'Employment of Foreigners: Foreign nationals may be employed in Lebanon only after obtaining a work permit from the Ministry of Labour. The work permit is granted based on the principle of priority for Lebanese workers and is subject to annual renewal.', 'en', 'Code of Labour (1946) - Expanded, Article 9', 'Employment of Foreigners', 'labor'),
  ('LB-LAB-001-EXPANDED', '10', 'Reciprocity Principle: The employment of foreign workers is subject to reciprocity with the worker''s country of origin. The Ministry of Labour may impose conditions on the employment of foreigners to protect the national labor market.', 'en', 'Code of Labour (1946) - Expanded, Article 10', 'Reciprocity Principle', 'labor'),
  ('LB-LAB-001-EXPANDED', '89', 'Labour Inspection: The Ministry of Labour shall appoint labour inspectors to supervise the implementation of this Code. Labour inspectors have the right to enter any establishment at any time to verify compliance with labor laws and regulations.', 'en', 'Code of Labour (1946) - Expanded, Article 89', 'Labour Inspection', 'labor'),
  ('LB-LAB-001-EXPANDED', '90', 'Penalties: Any employer who violates the provisions of this Code shall be liable to fines as determined by law. Repeated violations may result in closure of the establishment by order of the Ministry of Labour.', 'en', 'Code of Labour (1946) - Expanded, Article 90', 'Penalties', 'labor'),
  ('LB-LAB-001-EXPANDED', '56', 'Transfer of Enterprise: In the event of transfer of an enterprise by sale, merger, or succession, all employment contracts in force at the time of transfer shall remain binding on the new employer. Employees shall retain their rights and seniority.', 'en', 'Code of Labour (1946) - Expanded, Article 56', 'Transfer of Enterprise', 'labor'),
  ('LB-LAB-001-EXPANDED', '57', 'Employer''s Certificate: Upon termination of employment, the employer must provide the employee with a certificate of employment indicating the dates of commencement and termination, the nature of the work performed, and the last salary received. The employer may not include any unfavorable remarks in the certificate.', 'en', 'Code of Labour (1946) - Expanded, Article 57', 'Employer''s Certificate', 'labor'),
  ('LB-LAB-001-EXPANDED', '58', 'Workplace Register: Every employer must maintain a register of employees indicating their names, nationalities, dates of engagement, wages, and other particulars as required by regulation.', 'en', 'Code of Labour (1946) - Expanded, Article 58', 'Workplace Register', 'labor'),
  ('LB-LAB-001-EXPANDED', '59', 'Apprenticeship: An apprenticeship contract is a contract whereby an employer undertakes to provide vocational training to an apprentice who, in return, undertakes to work for the employer during the training period. The contract must be in writing and registered with the Ministry of Labour.', 'en', 'Code of Labour (1946) - Expanded, Article 59', 'Apprenticeship', 'labor'),
  ('LB-LAB-001-EXPANDED', '60', 'Non-Discrimination: No employer may discriminate between employees on the basis of sex, origin, religion, or belief in any aspect of employment, including recruitment, wages, working conditions, promotion, and termination.', 'en', 'Code of Labour (1946) - Expanded, Article 60', 'Non-Discrimination', 'labor'),
  ('LB-LAB-001-EXPANDED', NULL, 'The Lebanese Code of Labour was enacted on 23 September 1946, shortly after Lebanon''s independence. It remains the primary legislation governing employment relationships in Lebanon, covering individual and collective labor relations, working conditions, wages, termination, and labor disputes. Major amendments have been introduced over the decades, but the core framework remains in force.', 'en', 'Code of Labour (1946) - Expanded — Historical Context', 'Historical context and overview', 'labor'),
  ('LBN-LAB-001', '1', 'Définition de l''employeur', 'fr', 'Lebanese Labour Code, Article 1', 'Definitions', 'Labor Law'),
  ('LBN-LAB-001', '1', 'تعريف صاحب العمل', 'ar', 'Lebanese Labour Code, Article 1', 'Definitions', 'Labor Law'),
  ('LBN-LAB-001', '7', 'Exemptions - domestiques, travailleurs agricoles, entreprises familiales', 'fr', 'Lebanese Labour Code, Article 7', 'Scope Exemptions', 'Labor Law'),
  ('LBN-LAB-001', '7', 'استثناءات من القانون - الخدم المنزليين، العمال الزراعيين، المؤسسات العائلية', 'ar', 'Lebanese Labour Code, Article 7', 'Scope Exemptions', 'Labor Law'),
  ('LBN-LAB-001', '8', 'Champ d''application aux employeurs et travailleurs', 'fr', 'Lebanese Labour Code, Article 8', 'Scope of Application', 'Labor Law'),
  ('LBN-LAB-001', '8', 'نطاق تطبيق القانون على جميع أصحاب العمل والعمال', 'ar', 'Lebanese Labour Code, Article 8', 'Scope of Application', 'Labor Law'),
  ('LBN-LAB-001', '14', 'Salaire payable en monnaie légale', 'fr', 'Lebanese Labour Code, Article 14', 'Wage Payment', 'Labor Law'),
  ('LBN-LAB-001', '14', 'الأجر يدفع بالعملة القانونية', 'ar', 'Lebanese Labour Code, Article 14', 'Wage Payment', 'Labor Law'),
  ('LBN-LAB-001', '44', 'Salaire minimum doit couvrir les besoins essentiels', 'fr', 'Lebanese Labour Code, Article 44', 'Minimum Wage Principles', 'Labor Law'),
  ('LBN-LAB-001', '44', 'الحد الأدنى للأجر يجب أن يكفي للاحتياجات الأساسية', 'ar', 'Lebanese Labour Code, Article 44', 'Minimum Wage Principles', 'Labor Law'),
  ('LBN-LAB-001', '45', 'Commission de fixation du salaire minimum', 'fr', 'Lebanese Labour Code, Article 45', 'Minimum Wage Commission', 'Labor Law');
