  ('LBN-MIN-006', '1', 'Salaire minimum mensuel 28,000,000 LLP', 'fr', 'Decree Fixing Minimum Monthly and Daily Wages, Article 1', 'Monthly Minimum Wage', 'Labor Law'),
  ('LBN-MIN-006', '1', 'الحد الأدنى للأجر الشهري 28,000,000 ل.ل', 'ar', 'Decree Fixing Minimum Monthly and Daily Wages, Article 1', 'Monthly Minimum Wage', 'Labor Law'),
  ('LBN-MIN-006', '2', 'Salaire minimum journalier 1,300,000 LLP', 'fr', 'Decree Fixing Minimum Monthly and Daily Wages, Article 2', 'Daily Minimum Wage', 'Labor Law'),
  ('LBN-MIN-006', '2', 'الحد الأدنى للأجر اليومي 1,300,000 ل.ل', 'ar', 'Decree Fixing Minimum Monthly and Daily Wages, Article 2', 'Daily Minimum Wage', 'Labor Law'),
  ('LBN-MIN-006', '3', 'Révision du coût de vie dans les 6 mois suivant la publication', 'fr', 'Decree Fixing Minimum Monthly and Daily Wages, Article 3', 'Cost of Living Review', 'Labor Law'),
  ('LBN-MIN-006', '3', 'إعادة النظر بغلاء المعيشة خلال 6 أشهر من نشر المرسوم', 'ar', 'Decree Fixing Minimum Monthly and Daily Wages, Article 3', 'Cost of Living Review', 'Labor Law'),
  ('LBN-MIN-006', NULL, 'Latest minimum wage update as of August 2025. Minimum wage raised to LBP 28 million monthly (approximately $310 at market rate). NSSF maximum salary ceiling increased to LBP 140 million for maternity/sickness.', 'en', 'Decree Fixing Minimum Monthly and Daily Wages — Historical Context', 'Historical context and overview', 'Labor Law'),
  ('LBN-PEN-001', '1', 'Création d''un régime de retraite pour le secteur privé', 'fr', 'Law on Social Security Reform and Pension System Creation, Article 1', 'Pension System', 'Social Security'),
  ('LBN-PEN-001', '1', 'إنشاء نظام تقاعد للقطاع الخاص', 'ar', 'Law on Social Security Reform and Pension System Creation, Article 1', 'Pension System', 'Social Security'),
  ('LBN-PEN-001', '2', 'Adhésion obligatoire jusqu''à 48 ans, facultative pour 49+', 'fr', 'Law on Social Security Reform and Pension System Creation, Article 2', 'Coverage', 'Social Security'),
  ('LBN-PEN-001', '2', 'الاشتراك إلزامي للموظفين حتى 48 سنة، اختياري لمن هم فوق 49', 'ar', 'Law on Social Security Reform and Pension System Creation, Article 2', 'Coverage', 'Social Security'),
  ('LBN-PEN-001', '3', 'Âge de retraite 64 ans avec possibilité de départ anticipé à 60 ans', 'fr', 'Law on Social Security Reform and Pension System Creation, Article 3', 'Retirement Age', 'Social Security'),
  ('LBN-PEN-001', '3', 'سن التقاعد 64 سنة مع إمكانية التقاعد المبكر من 60 سنة', 'ar', 'Law on Social Security Reform and Pension System Creation, Article 3', 'Retirement Age', 'Social Security'),
  ('LBN-PEN-001', '4', '15 ans de cotisations minimum pour pension', 'fr', 'Law on Social Security Reform and Pension System Creation, Article 4', 'Qualifying Period', 'Social Security'),
  ('LBN-PEN-001', '4', '15 سنة اشتراك minimum للحصول على معاش', 'ar', 'Law on Social Security Reform and Pension System Creation, Article 4', 'Qualifying Period', 'Social Security'),
  ('LBN-PEN-001', '5', 'Comptes individuels notionnels - 12.25% du salaire cotisable', 'fr', 'Law on Social Security Reform and Pension System Creation, Article 5', 'Individual Accounts', 'Social Security'),
  ('LBN-PEN-001', '5', 'حسابات فردية افتراضية - 12.25% من الراتح الخاضع', 'ar', 'Law on Social Security Reform and Pension System Creation, Article 5', 'Individual Accounts', 'Social Security'),
  ('LBN-PEN-001', '6', 'Taux de cotisation combiné 17-18% (employé et employeur)', 'fr', 'Law on Social Security Reform and Pension System Creation, Article 6', 'Contribution Rate', 'Social Security'),
  ('LBN-PEN-001', '6', 'معدل مساهمة مجمع 17-18% (الموظف والمشغل)', 'ar', 'Law on Social Security Reform and Pension System Creation, Article 6', 'Contribution Rate', 'Social Security'),
  ('LBN-PEN-001', '7', 'Plafond des gains cotisables: 4 fois le salaire moyen des participants', 'fr', 'Law on Social Security Reform and Pension System Creation, Article 7', 'Earnings Cap', 'Social Security'),
  ('LBN-PEN-001', '7', 'الحد الأقصى للراتح الخاضع 4 أضعاف متوسط أجور جميع المشتركين', 'ar', 'Law on Social Security Reform and Pension System Creation, Article 7', 'Earnings Cap', 'Social Security'),
  ('LBN-PEN-001', '8', 'Nouveau conseil d''administration - 10 membres (4 travailleurs, 4 employeurs, 2 gouvernement)', 'fr', 'Law on Social Security Reform and Pension System Creation, Article 8', 'Governance', 'Social Security'),
  ('LBN-PEN-001', '8', 'هيئة إدارة جديدة - 10 أعضاء (4 عمال، 4 أصحاب عمل، 2 حكومة)', 'ar', 'Law on Social Security Reform and Pension System Creation, Article 8', 'Governance', 'Social Security'),
  ('LBN-PEN-001', '9', 'Comité d''investissement indépendant - révision actuarielle tous les 3 ans', 'fr', 'Law on Social Security Reform and Pension System Creation, Article 9', 'Investment Committee', 'Social Security'),
  ('LBN-PEN-001', '9', 'لجنة استثمار مستقلة - مراجعة اكتوارية كل 3 سنوات', 'ar', 'Law on Social Security Reform and Pension System Creation, Article 9', 'Investment Committee', 'Social Security'),
  ('LBN-PEN-001', NULL, 'Landmark reform passed after 20+ years of discussions. Replaces the end-of-service indemnity (EOSI) lump-sum system with a lifelong pension based on notional defined contribution (NDC). Addresses the severe underfunding of the previous system and provides old-age income security. Approximately 80% of elderly Lebanese were not receiving any pension before this reform.', 'en', 'Law on Social Security Reform and Pension System Creation — Historical Context', 'Historical context and overview', 'Social Security'),
  ('LBN-PAL-001', '9(3)', 'Exemption du réfugié palestinien de la réciprocité pour bénéficier de l''indemnité de fin de service', 'fr', 'Law Amending Article 9 of Social Security Law Regarding Palestinian Refugees, Article 9(3)', 'End of Service Benefit', 'Social Security'),
  ('LBN-PAL-001', '9(3)', 'إعفاء اللاجئ الفلسطيني من شرط المعاملة بالمثل للاستفادة من تعويض نهاية الخدمة', 'ar', 'Law Amending Article 9 of Social Security Law Regarding Palestinian Refugees, Article 9(3)', 'End of Service Benefit', 'Social Security'),
  ('LBN-PAL-001', 'Note', 'Non-bénéfice des branches maladie, maternité et allocations familiales - compte séparé pour cotisations', 'fr', 'Law Amending Article 9 of Social Security Law Regarding Palestinian Refugees, Article Note', 'Exclusions', 'Social Security'),
  ('LBN-PAL-001', 'Note', 'عدم الاستفادة من فروع المرض والأمومة والتعويضات العائلية - فتح حساب منفصل للمساهمات', 'ar', 'Law Amending Article 9 of Social Security Law Regarding Palestinian Refugees, Article Note', 'Exclusions', 'Social Security'),
  ('LBN-PAL-001', NULL, 'Adopted alongside Law 129/2010 amending Labor Code Article 59. First legal recognition of Palestinian refugees in Lebanese legislation. However, excludes them from health, maternity, and family benefits. Contributions (23.5%) same as Lebanese workers but only 8.5% goes to their end-of-service account.', 'en', 'Law Amending Article 9 of Social Security Law Regarding Palestinian Refugees — Historical Context', 'Historical context and overview', 'Social Security'),
  ('LBN-PAL-002', '59', 'Les travailleurs étrangers ont les mêmes droits que les travailleurs libanais sous réserve de réciprocité - le réfugié palestinien est exempté de réciprocité et frais de permis', 'fr', 'Law Amending Article 59 of Labour Code Regarding Palestinian Refugees, Article 59', 'Work Permit Exemption', 'Labor Law'),
  ('LBN-PAL-002', '59', 'العمال الأجانب لهم نفس حقوق العمال اللبنانيين عند الفصل بناء على سياسة المعاملة بالمثل - اللاجئ الفلسطيني معفى من شرط المعاملة بالمثل ورسوم تصريح العمل', 'ar', 'Law Amending Article 59 of Labour Code Regarding Palestinian Refugees, Article 59', 'Work Permit Exemption', 'Labor Law'),
  ('LBN-PAL-002', NULL, 'Historic amendment recognizing Palestinian refugees in Lebanese labor law. Exempts them from work permit fees and reciprocity principle. However, they still need work permits and are barred from liberal professions requiring syndicate membership (medicine, law, engineering, etc.).', 'en', 'Law Amending Article 59 of Labour Code Regarding Palestinian Refugees — Historical Context', 'Historical context and overview', 'Labor Law'),
  ('LBN-PUB-001', 'Various', 'Nomination à la fonction publique - conditions et procédures', 'fr', 'Decree-Law on Civil Servants Regulation, Article Various', 'Appointment', 'Labor Law'),
  ('LBN-PUB-001', 'Various', 'التعيين في الوظيفة العامة - الشروط والإجراءات', 'ar', 'Decree-Law on Civil Servants Regulation, Article Various', 'Appointment', 'Labor Law'),
  ('LBN-PUB-001', 'Various', 'Échelle des grades et salaires', 'fr', 'Decree-Law on Civil Servants Regulation, Article Various', 'Salary Scale', 'Labor Law'),
  ('LBN-PUB-001', 'Various', 'سلسلة الرتب والرواتب', 'ar', 'Decree-Law on Civil Servants Regulation, Article Various', 'Salary Scale', 'Labor Law'),
  ('LBN-PUB-001', 'Various', 'Retraite dans le secteur public', 'fr', 'Decree-Law on Civil Servants Regulation, Article Various', 'Retirement', 'Labor Law'),
  ('LBN-PUB-001', 'Various', 'التقاعد في القطاع العام', 'ar', 'Decree-Law on Civil Servants Regulation, Article Various', 'Retirement', 'Labor Law'),
  ('LBN-PUB-001', NULL, 'Primary legislation governing public sector employment in Lebanon. Establishes the civil service framework, salary scales, promotion criteria, and retirement system for government employees.', 'en', 'Decree-Law on Civil Servants Regulation — Historical Context', 'Historical context and overview', 'Labor Law'),
  ('LBN-PUB-002', '1', 'Modification de l''échelle des grades pour les cinq catégories', 'fr', 'Law on Public Sector Salary Scale, Article 1', 'Salary Scale', 'Labor Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LBN-PUB-002', '1', 'تعديل سلسلة الرتب والرواتب للفئات الخمس', 'ar', 'Law on Public Sector Salary Scale, Article 1', 'Salary Scale', 'Labor Law'),
  ('LBN-PUB-002', '2', 'Salaire minimum 675,000 LLP', 'fr', 'Law on Public Sector Salary Scale, Article 2', 'Minimum Salary', 'Labor Law'),
  ('LBN-PUB-002', '2', 'الحد الأدنى للراتب 675,000 ل.ل', 'ar', 'Law on Public Sector Salary Scale, Article 2', 'Minimum Salary', 'Labor Law'),
  ('LBN-PUB-002', NULL, 'Major reform of public sector salaries after years of stagnation. Unified salary scale across government sectors. Set minimum wage at LBP 675,000 matching private sector. Significant increases for teachers and military personnel.', 'en', 'Law on Public Sector Salary Scale — Historical Context', 'Historical context and overview', 'Labor Law'),
  ('LBN-ILO-001', '1', 'Ratification de la Convention OIT n° 131', 'fr', 'Legislative Decree 70/1977 - Ratification of ILO Convention 131, Article 1', 'ILO Convention Ratification', 'Labor Law'),
  ('LBN-ILO-001', '1', 'المصادقة على اتفاقية العمل الدولية رقم 131', 'ar', 'Legislative Decree 70/1977 - Ratification of ILO Convention 131, Article 1', 'ILO Convention Ratification', 'Labor Law'),
  ('LBN-ILO-001', NULL, 'Ratified ILO Convention 131 on Minimum Wage Fixing, establishing international standards for minimum wage determination through tripartite consultation.', 'en', 'Legislative Decree 70/1977 - Ratification of ILO Convention 131 — Historical Context', 'Historical context and overview', 'Labor Law'),
  ('LBN-ARB-001', '1', 'Ratification de la Convention arabe n° 15', 'fr', 'Law 183/2000 - Ratification of Arab Convention 15, Article 1', 'Arab Convention Ratification', 'Labor Law'),
  ('LBN-ARB-001', '1', 'المصادقة على الاتفاقية العربية رقم 15', 'ar', 'Law 183/2000 - Ratification of Arab Convention 15, Article 1', 'Arab Convention Ratification', 'Labor Law'),
  ('LBN-ARB-001', NULL, 'Ratified Arab Labor Convention 15 (1983) on wage determination and protection. References Article 7 on employee''s right to full salary even when not performing work for reasons beyond their control.', 'en', 'Law 183/2000 - Ratification of Arab Convention 15 — Historical Context', 'Historical context and overview', 'Labor Law'),
  ('LBN-ALL-001', '1', '40,000,000 LLP par étudiant écoles publiques et UL (max 120,000,000 LLP)', 'fr', 'Decree on Schooling Allowance for Academic Year 2024-2025, Article 1', 'Public Schools', 'Labor Law'),
  ('LBN-ALL-001', '1', '40,000,000 ل.ل للطالب في المدارس الرسمية والجامعة اللبنانية (حد أقصى 120,000,000 ل.ل)', 'ar', 'Decree on Schooling Allowance for Academic Year 2024-2025, Article 1', 'Public Schools', 'Labor Law'),
  ('LBN-ALL-001', '2', '12,000,000 LLP par étudiant écoles et universités privées (max 36,000,000 LLP)', 'fr', 'Decree on Schooling Allowance for Academic Year 2024-2025, Article 2', 'Private Schools', 'Labor Law'),
  ('LBN-ALL-001', '2', '12,000,000 ل.ل للطالب في المدارس والجامعات الخاصة (حد أقصى 36,000,000 ل.ل)', 'ar', 'Decree on Schooling Allowance for Academic Year 2024-2025, Article 2', 'Private Schools', 'Labor Law'),
  ('LBN-ALL-001', NULL, 'Annual decree setting schooling allowances for employees'' children. Separate rates for public and private education.', 'en', 'Decree on Schooling Allowance for Academic Year 2024-2025 — Historical Context', 'Historical context and overview', 'Labor Law'),
  ('LBN-NSS-002', '68(2)', 'Plafond maternité/maladie 120,000,000 LLP (était 90,000,000 LLP)', 'fr', 'Decree Amending Article 68 of Social Security Law - Maternity/Sickness Ceiling Increase, Article 68(2)', 'Maternity/Sickness Ceiling', 'Social Security'),
  ('LBN-NSS-002', '68(2)', 'الحد الأقصى للراتح الخاضع لاقتطاعات الأمومة والمرض 120,000,000 ل.ل (كان 90,000,000 ل.ل)', 'ar', 'Decree Amending Article 68 of Social Security Law - Maternity/Sickness Ceiling Increase, Article 68(2)', 'Maternity/Sickness Ceiling', 'Social Security'),
  ('LBN-NSS-002', NULL, 'Increased NSSF ceiling for maternity and sickness contributions from LBP 90 million to LBP 120 million monthly.', 'en', 'Decree Amending Article 68 of Social Security Law - Maternity/Sickness Ceiling Increase — Historical Context', 'Historical context and overview', 'Social Security'),
  ('LBN-NSS-003', '1', 'Allocation familiale conjoint: 1,200,000 LLP', 'fr', 'Decree Amending Social Security Family Allowances, Article 1', 'Spouse Allowance', 'Social Security'),
  ('LBN-NSS-003', '1', 'تعويض عائلي للزوج/الزوجة: 1,200,000 ل.ل', 'ar', 'Decree Amending Social Security Family Allowances, Article 1', 'Spouse Allowance', 'Social Security'),
  ('LBN-NSS-003', '2', 'Allocation familiale enfant: 660,000 LLP (max 5 enfants)', 'fr', 'Decree Amending Social Security Family Allowances, Article 2', 'Child Allowance', 'Social Security'),
  ('LBN-NSS-003', '2', 'تعويض عائلي للطفل: 660,000 ل.ل (حد أقصى 5 أطفال)', 'ar', 'Decree Amending Social Security Family Allowances, Article 2', 'Child Allowance', 'Social Security'),
  ('LBN-NSS-003', '3', 'Total maximum allocations familiales: 4,500,000 LLP', 'fr', 'Decree Amending Social Security Family Allowances, Article 3', 'Total Cap', 'Social Security'),
  ('LBN-NSS-003', '3', 'المجموع الأقصى للتعويضات العائلية: 4,500,000 ل.ل', 'ar', 'Decree Amending Social Security Family Allowances, Article 3', 'Total Cap', 'Social Security'),
  ('LBN-NSS-003', '4', 'Plafond cotisations allocations familiales: 18,000,000 LLP', 'fr', 'Decree Amending Social Security Family Allowances, Article 4', 'Contribution Ceiling', 'Social Security'),
  ('LBN-NSS-003', '4', 'الحد الأقصى للراتح الخاضع لاقتطاعات التعويضات العائلية: 18,000,000 ل.ل', 'ar', 'Decree Amending Social Security Family Allowances, Article 4', 'Contribution Ceiling', 'Social Security'),
  ('LBN-NSS-003', NULL, 'Significant increase in family allowances. Also raised the contribution ceiling from LBP 12 million to LBP 18 million.', 'en', 'Decree Amending Social Security Family Allowances — Historical Context', 'Historical context and overview', 'Social Security'),
  ('LBN-NSS-004', '68(2)', 'Plafond allocations familiales 12,000,000 LLP (était 2,825,000 LLP)', 'fr', 'Decree Amending NSSF Ceiling - Family Allowances, Article 68(2)', 'Family Allowance Ceiling', 'Social Security'),
  ('LBN-NSS-004', '68(2)', 'الحد الأقصى للراتح الخاضع لاقتطاعات التعويضات العائلية 12,000,000 ل.ل (كان 2,825,000 ل.ل)', 'ar', 'Decree Amending NSSF Ceiling - Family Allowances, Article 68(2)', 'Family Allowance Ceiling', 'Social Security'),
  ('LBN-NSS-004', NULL, 'First major increase in NSSF family allowance ceiling in years. Raised from LBP 2.825 million to LBP 12 million.', 'en', 'Decree Amending NSSF Ceiling - Family Allowances — Historical Context', 'Historical context and overview', 'Social Security'),
  ('LBN-TRA-001', '1', 'Criminalisation de la traite des personnes', 'fr', 'Anti-Trafficking Law, Article 1', 'Trafficking Prohibition', 'Labor Law'),
  ('LBN-TRA-001', '1', 'تجريم الاتجار بالأشخاص', 'ar', 'Anti-Trafficking Law, Article 1', 'Trafficking Prohibition', 'Labor Law'),
  ('LBN-TRA-001', '2', 'Peine 5-15 ans pour traite d''êtres humains', 'fr', 'Anti-Trafficking Law, Article 2', 'Penalties', 'Labor Law'),
  ('LBN-TRA-001', '2', 'عقوبة السجن 5-15 سنة للاتجار بالبشر', 'ar', 'Anti-Trafficking Law, Article 2', 'Penalties', 'Labor Law'),
  ('LBN-TRA-001', NULL, 'Lebanon''s primary anti-trafficking legislation. Addresses forced labor and sex trafficking. Important for protecting migrant workers under the kafala system.', 'en', 'Anti-Trafficking Law — Historical Context', 'Historical context and overview', 'Labor Law'),
  ('LBN-FOR-001', 'Various', 'Procédures d''entrée des étrangers', 'fr', 'Decree Amending Decree 10188/1962 on Foreigners Entry, Stay and Exit, Article Various', 'Entry Procedures', 'Labor Law'),
  ('LBN-FOR-001', 'Various', 'إجراءات دخول الأجانب', 'ar', 'Decree Amending Decree 10188/1962 on Foreigners Entry, Stay and Exit, Article Various', 'Entry Procedures', 'Labor Law'),
  ('LBN-FOR-001', 'Various', 'Procédures de séjour', 'fr', 'Decree Amending Decree 10188/1962 on Foreigners Entry, Stay and Exit, Article Various', 'Stay Procedures', 'Labor Law'),
  ('LBN-FOR-001', 'Various', 'إجراءات الإقامة', 'ar', 'Decree Amending Decree 10188/1962 on Foreigners Entry, Stay and Exit, Article Various', 'Stay Procedures', 'Labor Law'),
  ('LBN-FOR-001', NULL, 'Amended the 1962 law on foreign entry and stay. Part of the legal framework governing foreign workers in Lebanon.', 'en', 'Decree Amending Decree 10188/1962 on Foreigners Entry, Stay and Exit — Historical Context', 'Historical context and overview', 'Labor Law'),
  ('LBN-FOR-002', 'Various', 'Permis de travail pour étrangers', 'fr', 'By-Law 17561/1964 Regulating Work of Foreigners in Lebanon, Article Various', 'Work Permits', 'Labor Law'),
  ('LBN-FOR-002', 'Various', 'تصاريح العمل للأجانب', 'ar', 'By-Law 17561/1964 Regulating Work of Foreigners in Lebanon, Article Various', 'Work Permits', 'Labor Law'),
  ('LBN-FOR-002', 'Various', 'Conditions d''emploi des étrangers', 'fr', 'By-Law 17561/1964 Regulating Work of Foreigners in Lebanon, Article Various', 'Employment Conditions', 'Labor Law'),
  ('LBN-FOR-002', 'Various', 'شروط تشغيل الأجانب', 'ar', 'By-Law 17561/1964 Regulating Work of Foreigners in Lebanon, Article Various', 'Employment Conditions', 'Labor Law'),
  ('LBN-FOR-002', NULL, 'Primary regulation governing foreign worker permits in Lebanon. Requires 3 Lebanese workers per foreign worker (not always strictly enforced).', 'en', 'By-Law 17561/1964 Regulating Work of Foreigners in Lebanon — Historical Context', 'Historical context and overview', 'Labor Law'),
  ('LBN-FOR-003', '1', 'Professions administratives et bancaires réservées aux Libanais', 'fr', 'Minister of Labor Decision 1/41/2017 on Occupations Reserved for Lebanese Nationals, Article 1', 'Reserved Occupations', 'Labor Law'),
  ('LBN-FOR-003', '1', 'المهن الإدارية والمصرفية محصورة باللبنانيين', 'ar', 'Minister of Labor Decision 1/41/2017 on Occupations Reserved for Lebanese Nationals, Article 1', 'Reserved Occupations', 'Labor Law'),
  ('LBN-FOR-003', '2', 'Exception si expertise non disponible localement', 'fr', 'Minister of Labor Decision 1/41/2017 on Occupations Reserved for Lebanese Nationals, Article 2', 'Exceptions', 'Labor Law'),
  ('LBN-FOR-003', '2', 'استثناء إذا كانت الخبرة غير متوفرة محليا', 'ar', 'Minister of Labor Decision 1/41/2017 on Occupations Reserved for Lebanese Nationals, Article 2', 'Exceptions', 'Labor Law'),
  ('LBN-FOR-003', NULL, 'Annual list of occupations reserved for Lebanese nationals. Updated yearly by Ministry of Labor. Foreigners can be granted permits for these positions only if their specialization is not available locally.', 'en', 'Minister of Labor Decision 1/41/2017 on Occupations Reserved for Lebanese Nationals — Historical Context', 'Historical context and overview', 'Labor Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LBN-OPT-001', '1', 'Droit de tout Libanais d''adhérer facultativement à sécurité sociale', 'fr', 'Law 248/2000 - Optional Social Security, Article 1', 'Voluntary Coverage', 'Social Security'),
  ('LBN-OPT-001', '1', 'حق كل لبناني في الانتساب الاختياري للضمان الاجتماعي', 'ar', 'Law 248/2000 - Optional Social Security, Article 1', 'Voluntary Coverage', 'Social Security'),
  ('LBN-OPT-001', '2', 'Conditions: 64 ans, ne pas bénéficier d''autre assurance santé', 'fr', 'Law 248/2000 - Optional Social Security, Article 2', 'Conditions', 'Social Security'),
  ('LBN-OPT-001', '2', 'شروط الانتساب: بلوغ 64 سنة، عدم الانتفاع من تأمين صحي آخر', 'ar', 'Law 248/2000 - Optional Social Security, Article 2', 'Conditions', 'Social Security'),
  ('LBN-OPT-001', NULL, 'Created optional social security coverage for those not covered by mandatory scheme, particularly elderly. Implementation started in 2002 with Decree 7352 but has faced operational challenges.', 'en', 'Law 248/2000 - Optional Social Security — Historical Context', 'Historical context and overview', 'Social Security'),
  ('LBN-RET-001', '1', 'Permettre aux retraités de bénéficier maladie/maternité', 'fr', 'Law 27/2017 - Allowing Retirees to Benefit from Sickness and Maternity Branches, Article 1', 'Retiree Health Coverage', 'Social Security'),
  ('LBN-RET-001', '1', 'السماح للمتقاعدين بالانتفاع من فروع المرض والأمومة', 'ar', 'Law 27/2017 - Allowing Retirees to Benefit from Sickness and Maternity Branches, Article 1', 'Retiree Health Coverage', 'Social Security'),
  ('LBN-RET-001', '2', 'Condition d''affiliation effective 20 ans minimum', 'fr', 'Law 27/2017 - Allowing Retirees to Benefit from Sickness and Maternity Branches, Article 2', 'Qualifying Period', 'Social Security'),
  ('LBN-RET-001', '2', 'شرط الانتساب الفعلي 20 سنة على الأقل', 'ar', 'Law 27/2017 - Allowing Retirees to Benefit from Sickness and Maternity Branches, Article 2', 'Qualifying Period', 'Social Security'),
  ('LBN-RET-001', NULL, 'Important expansion of NSSF coverage allowing retirees to access healthcare. However, requires 20 years of actual enrollment, excluding many contract workers.', 'en', 'Law 27/2017 - Allowing Retirees to Benefit from Sickness and Maternity Branches — Historical Context', 'Historical context and overview', 'Social Security'),
  ('LBN-TRA-002', '1', 'Allocation transport journalière 65,000 LLP (était 24,000 LLP)', 'fr', 'Decree Increasing Transportation Allowance, Article 1', 'Transportation Allowance', 'Labor Law'),
  ('LBN-TRA-002', '1', 'بدل النقل اليومي 65,000 ل.ل (كان 24,000 ل.ل)', 'ar', 'Decree Increasing Transportation Allowance, Article 1', 'Transportation Allowance', 'Labor Law'),
  ('LBN-TRA-002', NULL, 'Increased daily transportation allowance from LBP 24,000 to LBP 65,000 during economic crisis.', 'en', 'Decree Increasing Transportation Allowance — Historical Context', 'Historical context and overview', 'Labor Law'),
  ('LBN-TRA-003', '1', 'Allocation transport journalière 95,000 LLP (était 65,000 LLP)', 'fr', 'Decree Amending Transportation Allowance, Article 1', 'Transportation Allowance', 'Labor Law'),
  ('LBN-TRA-003', '1', 'بدل النقل اليومي 95,000 ل.ل (كان 65,000 ل.ل)', 'ar', 'Decree Amending Transportation Allowance, Article 1', 'Transportation Allowance', 'Labor Law'),
  ('LBN-TRA-003', NULL, 'Further increase to transportation allowance from LBP 65,000 to LBP 95,000.', 'en', 'Decree Amending Transportation Allowance — Historical Context', 'Historical context and overview', 'Labor Law'),
  ('LBN-WOR-001', '1', 'Indemnité incapacité temporaire: 75% salaire journalier', 'fr', 'Work Injury Law 1943, Article 1', 'Temporary Disability', 'Labor Law'),
  ('LBN-WOR-001', '1', 'تعويض العجز المؤقت: 75% من الأجر اليومي', 'ar', 'Work Injury Law 1943, Article 1', 'Temporary Disability', 'Labor Law'),
  ('LBN-WOR-001', '2', 'Indemnité incapacité permanente: 800 jours <35 ou >50, 700 jours 35-50', 'fr', 'Work Injury Law 1943, Article 2', 'Permanent Disability', 'Labor Law'),
  ('LBN-WOR-001', '2', 'تعويض العجز الدائم: 800 يوم عمل للأعمار تحت 35 أو فوق 50، 700 يوم للأعمار 35-50', 'ar', 'Work Injury Law 1943, Article 2', 'Permanent Disability', 'Labor Law'),
  ('LBN-WOR-001', NULL, 'Pre-dates Labor Code 1946. Employer-liability system for work injuries. Provides temporary and permanent disability benefits. Administered through NSSF which contracts with hospitals for medical care.', 'en', 'Work Injury Law 1943 — Historical Context', 'Historical context and overview', 'Labor Law'),
  ('LBN-FAM-001', '1', 'Allocation épouse: 60,000 LLP (ancien) - maintenant 1,200,000 LLP', 'fr', 'Family Allowances Decree 1965, Article 1', 'Spouse Allowance', 'Social Security'),
  ('LBN-FAM-001', '1', 'تعويض عائلي للزوجة: 60,000 ل.ل (قديم) - الآن 1,200,000 ل.ل', 'ar', 'Family Allowances Decree 1965, Article 1', 'Spouse Allowance', 'Social Security'),
  ('LBN-FAM-001', '2', 'Allocation enfant: 33,000 LLP (ancien) - maintenant 660,000 LLP (max 5)', 'fr', 'Family Allowances Decree 1965, Article 2', 'Child Allowance', 'Social Security'),
  ('LBN-FAM-001', '2', 'تعويض للطفل: 33,000 ل.ل (قديم) - الآن 660,000 ل.ل (حد أقصى 5 أطفال)', 'ar', 'Family Allowances Decree 1965, Article 2', 'Child Allowance', 'Social Security'),
  ('LBN-FAM-001', NULL, 'Implemented family allowances system under Social Security Law. Originally provided LBP 60,000 for wife and LBP 33,000 per child (max 5). Significantly increased in 2025 to LBP 1.2 million for spouse and LBP 660,000 per child.', 'en', 'Family Allowances Decree 1965 — Historical Context', 'Historical context and overview', 'Social Security'),
  ('LBN-JUD-001', 'Various', 'Tableau salaires juges actualisé', 'fr', 'Law 173/2011 - Raising Judges'' Salaries, Article Various', 'Judicial Salaries', 'Labor Law'),
  ('LBN-JUD-001', 'Various', 'جدول رواتب القضاة المحدث', 'ar', 'Law 173/2011 - Raising Judges'' Salaries, Article Various', 'Judicial Salaries', 'Labor Law'),
  ('LBN-JUD-001', NULL, 'Updated salary scale for judges. Highest judicial salary was approximately $6,233 before currency collapse, now worth about $995.', 'en', 'Law 173/2011 - Raising Judges'' Salaries — Historical Context', 'Historical context and overview', 'Labor Law'),
  ('LBN-EDU-001', 'Various', 'Tableau salaires professeurs UL', 'fr', 'Law 206/2012 - Raising Lebanese University Professors'' Salaries, Article Various', 'University Salaries', 'Labor Law'),
  ('LBN-EDU-001', 'Various', 'جدول رواتب أساتذة الجامعة اللبنانية', 'ar', 'Law 206/2012 - Raising Lebanese University Professors'' Salaries, Article Various', 'University Salaries', 'Labor Law'),
  ('LBN-EDU-001', NULL, 'Updated salary scale for Lebanese University professors. Highest professor salary was approximately $5,617 before currency collapse, now worth about $896.', 'en', 'Law 206/2012 - Raising Lebanese University Professors'' Salaries — Historical Context', 'Historical context and overview', 'Labor Law'),
  ('LB-LAB-001', '1-6', 'Scope of application. Applies to employers and employees in commercial, industrial, and agricultural establishments. Excludes public servants, domestic workers (until recent amendments), and agricultural workers (partially).', 'en', 'Labor Code / Labour Law, Article 1-6', 'Scope and application', 'Labor & Social Security'),
  ('LB-LAB-001', '26', 'Non-discrimination: prohibition of discrimination in employment on basis of sex (equal pay provisions, though limited in scope).', 'en', 'Labor Code / Labour Law, Article 26', 'Non-discrimination', 'Labor & Social Security'),
  ('LB-LAB-001', '27', 'Working hours and conditions. Maximum 48 hours per week. Special provisions for hazardous work.', 'en', 'Labor Code / Labour Law, Article 27', 'Working hours', 'Labor & Social Security'),
  ('LB-LAB-001', '28-29', 'Maternity leave provisions: pre- and post-natal leave entitlements.', 'en', 'Labor Code / Labour Law, Article 28-29', 'Maternity leave', 'Labor & Social Security'),
  ('LB-LAB-001', '50', 'Right to organize and form trade unions. Freedom to unionize or not to unionize.', 'en', 'Labor Code / Labour Law, Article 50', 'Freedom of association', 'Labor & Social Security'),
  ('LB-LAB-001', '52-74', 'Termination of employment: end of service indemnity (severance), notice periods, arbitrary dismissal compensation.', 'en', 'Labor Code / Labour Law, Article 52-74', 'Termination and severance', 'Labor & Social Security'),
  ('LB-LAB-001', NULL, 'Enacted after twenty years of intense workers'' mobilizations in tobacco, typography, transport, petroleum, and port sectors. Governs private and mixed sector employment. Public sector regulated by separate Decree-Law 112/1959. Notable exclusions historically included domestic workers, agricultural workers, and family businesses. Domestic workers were partially covered by Law No. 41/2024. The Labor Code requires prior authorization from the Ministry of Labour for trade union formation, which has been criticized by ILO committees. Lebanon has ratified most core ILO conventions.', 'en', 'Labor Code / Labour Law — Historical Context', 'Historical context and overview', 'Labor & Social Security'),
  ('LB-LAB-001', NULL, 'Amended on various occasions, most recently in May 2025. Key amendments have addressed working hours, maternity leave, minimum wage, child labor, and worker protections.', 'en', 'Labor Code / Labour Law — Amendment: Various amendments (1946-2025)', 'Amendment', 'Labor & Social Security'),
  ('LB-LAB-001', NULL, 'Set statutory minimum wage at LBP 675,000/month (approximately $450 at pre-crisis exchange rate). This decree implemented wage increases through amendments to the Labor Code.', 'en', 'Labor Code / Labour Law — Amendment: Decree No. 7426/2012 (Minimum Wage)', 'Amendment', 'Labor & Social Security'),
  ('LB-LAB-002', '1-8', 'Establishment of the National Social Security Fund (NSSF / الصندوق الوطني للضمان الاجتماعي). Three branches: Sickness and Maternity, Family Allowances, End of Service Indemnity.', 'en', 'Social Security Act / National Social Security Fund (NSSF) Law, Article 1-8', 'NSSF establishment and branches', 'Labor & Social Security'),
  ('LB-LAB-002', '26', 'Maternity benefits: cash benefits during maternity leave.', 'en', 'Social Security Act / National Social Security Fund (NSSF) Law, Article 26', 'Maternity benefits', 'Labor & Social Security'),
  ('LB-LAB-002', NULL, 'Established Lebanon''s social security system through the National Social Security Fund (NSSF). Originally planned to have four branches, but only three have been fully implemented: Sickness and Maternity, Family Allowances, and End of Service Indemnity. A retirement/pension branch has never been implemented despite decades of discussion. The NSSF covers employees registered in the private sector. Self-employed persons and informal workers largely remain excluded. The fund has faced severe financial difficulties, particularly since the 2019 economic crisis.', 'en', 'Social Security Act / National Social Security Fund (NSSF) Law — Historical Context', 'Historical context and overview', 'Labor & Social Security'),
  ('LB-LAB-002', NULL, 'Began implementation of optional social security in the Sickness and Maternity Branch of NSSF.', 'en', 'Social Security Act / National Social Security Fund (NSSF) Law — Amendment: Decree No. 7352/2002 (Optional Social Security)', 'Amendment', 'Labor & Social Security'),
  ('LB-LAB-003', NULL, 'Governs employment of civil servants in the public sector. Separate from the Labor Code which covers private sector. Establishes rights, obligations, disciplinary procedures, and career paths for government employees. Confessional balance requirements apply to public sector appointments under the Constitution.', 'en', 'Civil Servants Regulation / Public Employment Law — Historical Context', 'Historical context and overview', 'Labor & Social Security'),
  ('LB-LAB-004', NULL, 'Established the Central Investigation Office (التفتيش المركزي), an oversight body for public administration. Exercises supervisory control over government ministries and agencies.', 'en', 'Central Investigation/Inspection Office Law — Historical Context', 'Historical context and overview', 'Labor & Social Security'),
  ('LB-LAB-005', NULL, 'Regulates work-related accidents and occupational injuries. Applies to both Lebanese and foreign employees. Establishes employer liability for workplace accidents and occupational diseases.', 'en', 'Work Accidents Law / Occupational Injuries — Historical Context', 'Historical context and overview', 'Labor & Social Security'),
  ('LB-LAB-006', NULL, 'Establishes the labor arbitration council system for resolving labor disputes. Each council consists of a judge (presiding), a workers'' representative, and an employers'' representative. Decisions can be challenged by objection, third-party objection, and cassation.', 'en', 'Decree on the Authorities of Arbitration Labour Councils — Historical Context', 'Historical context and overview', 'Labor & Social Security'),
  ('LB-LAB-007', NULL, 'Regulates employment of foreign nationals in Lebanon. Requires work permits and residency permits for legal employment. Sets out permit categories and restrictions by profession. Frequently discussed in the context of Syrian and Palestinian workers in Lebanon.', 'en', 'Foreign Workers Regulation — Historical Context', 'Historical context and overview', 'Labor & Social Security');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-LAB-008', NULL, 'Comprehensive occupational safety and health regulation implementing the Labor Code. Establishes prevention and safety requirements for all establishments subject to the Labor Code.', 'en', 'Occupational Prevention, Safety and Hygiene Regulation — Historical Context', 'Historical context and overview', 'Labor & Social Security'),
