  ('LD-1920-336', '14', 'Le service de la Justice, des Propriétés et des Wakfs est classé troisième parmi les sept services de l''État', 'fr', 'Decree No. 336 on the Interim Bylaws of the State of Greater Lebanon, Article 14', 'Organization of State Services - Justice Department', 'Legislative Decree - Mandate Period'),
  ('LD-1920-336', '14', 'مصلحة العدلية والأملاك والأوقاف تحتل المرتبة الثالثة بين سبع خدمات للدولة', 'ar', 'Decree No. 336 on the Interim Bylaws of the State of Greater Lebanon, Article 14', 'Organization of State Services - Justice Department', 'Legislative Decree - Mandate Period'),
  ('LD-1920-336', NULL, 'French Mandate period - High Commissioner General Gouraud issued this decree the day after the proclamation of Greater Lebanon, establishing the administrative structure', 'en', 'Decree No. 336 on the Interim Bylaws of the State of Greater Lebanon — Historical Context', 'Historical context and overview', 'Legislative Decree - Mandate Period'),
  ('LD-1920-086', '1', 'Il est créé une Direction de la Justice chargée d''organiser et de gérer les services judiciaires', 'fr', 'Decree No. 86 Establishing the Directorate of Justice, Article 1', 'Establishment of Directorate of Justice', 'Legislative Decree - Mandate Period'),
