  ('LD-1920-343', '1', 'تعيين شارل دباس مديراً للعدلية', 'ar', 'Decree No. 343 Appointing Charles Débbas as First Director of Justice, Article 1', 'First Director of Justice appointment', 'Legislative Decree - Mandate Period'),
  ('LD-1920-343', NULL, 'French Mandate period - High Commissioner General Gouraud appointed Charles Débbas, who later became the first President of Lebanon in 1926', 'en', 'Decree No. 343 Appointing Charles Débbas as First Director of Justice — Historical Context', 'Historical context and overview', 'Legislative Decree - Mandate Period'),
