  ('LD-1932-COC', NULL, 'French Mandate period - The most notable code promulgated during the French Mandate, equivalent to the French Civil Code except for personal status matters. Still in force today with amendments.', 'en', 'Code of Obligations and Contracts of March 9, 1932 — Historical Context', 'Historical context and overview', 'Legislative Decree - Mandate Period'),
  ('LD-1924-2385', '1', 'Toute invention industrielle créant un bénéfice pour son propriétaire, celui-ci seul a le droit de l''exploiter', 'fr', 'Resolution No. 2385 of January 17, 1924 on the System of Commercial and Industrial Property Rights, Article 1', 'Invention Rights', 'Legislative Decree - Mandate Period'),
  ('LD-1924-2385', '1', 'لكل اختراع صناعي يحقق منفعة لصاحب له الحق في استغلاله', 'ar', 'Resolution No. 2385 of January 17, 1924 on the System of Commercial and Industrial Property Rights, Article 1', 'Invention Rights', 'Legislative Decree - Mandate Period'),
  ('LD-1924-2385', '2', 'Un certificat peut être accordé pour chaque invention relative à un nouveau produit industriel', 'fr', 'Resolution No. 2385 of January 17, 1924 on the System of Commercial and Industrial Property Rights, Article 2', 'Invention Certificates', 'Legislative Decree - Mandate Period'),
  ('LD-1924-2385', '2', 'يمنح شهادة لكل اختراع متعلق بمنتج صناعي جديد', 'ar', 'Resolution No. 2385 of January 17, 1924 on the System of Commercial and Industrial Property Rights, Article 2', 'Invention Certificates', 'Legislative Decree - Mandate Period'),
  ('LD-1924-2385', NULL, 'French Mandate period - High Commissioner General Wegan issued this resolution establishing intellectual property protection in Syria and Lebanon under French mandate', 'en', 'Resolution No. 2385 of January 17, 1924 on the System of Commercial and Industrial Property Rights — Historical Context', 'Historical context and overview', 'Legislative Decree - Mandate Period'),
  ('LD-1926-CONSTITUTION', '1', 'Le Liban est une République, sa capitale est Beyrouth', 'fr', 'Constitution of the Lebanese Republic of May 23, 1926, Article 1', 'Form of State', 'Legislative Decree - Mandate Period'),
  ('LD-1926-CONSTITUTION', '1', 'لبنان جمهورية، عاصمتها بيروت', 'ar', 'Constitution of the Lebanese Republic of May 23, 1926, Article 1', 'Form of State', 'Legislative Decree - Mandate Period'),
  ('LD-1926-CONSTITUTION', '9', 'La liberté de conscience est absolue, l''État respecte tous les cultes et religions', 'fr', 'Constitution of the Lebanese Republic of May 23, 1926, Article 9', 'Freedom of Conscience', 'Legislative Decree - Mandate Period'),
  ('LD-1926-CONSTITUTION', '9', 'الحرية الضميرية مطلقة، الدولة تحترم جميع الأديان والمذاهب', 'ar', 'Constitution of the Lebanese Republic of May 23, 1926, Article 9', 'Freedom of Conscience', 'Legislative Decree - Mandate Period'),
  ('LD-1926-CONSTITUTION', '20', 'Les juges sont indépendants dans l''exercice de leurs fonctions', 'fr', 'Constitution of the Lebanese Republic of May 23, 1926, Article 20', 'Judicial Independence', 'Legislative Decree - Mandate Period'),
  ('LD-1926-CONSTITUTION', '20', 'القضاة مستقلون في وظائفهم', 'ar', 'Constitution of the Lebanese Republic of May 23, 1926, Article 20', 'Judicial Independence', 'Legislative Decree - Mandate Period'),
  ('LD-1926-CONSTITUTION', '24', 'La représentation parlementaire est basée sur l''égalité entre chrétiens et musulmans', 'fr', 'Constitution of the Lebanese Republic of May 23, 1926, Article 24', 'Confessional Representation', 'Legislative Decree - Mandate Period'),
  ('LD-1926-CONSTITUTION', '24', 'التمثيل النيابي على أساس المساواة بين المسيحيين والمسلمين', 'ar', 'Constitution of the Lebanese Republic of May 23, 1926, Article 24', 'Confessional Representation', 'Legislative Decree - Mandate Period'),
  ('LD-1926-CONSTITUTION', NULL, 'French Mandate period - The Lebanese Constitution was adopted on May 23, 1926, drafted primarily by French authorities with limited Lebanese input. It established the confessional system and was inspired by the French Third Republic. Articles 90-94 relating to the Mandate were abolished in 1943.', 'en', 'Constitution of the Lebanese Republic of May 23, 1926 — Historical Context', 'Historical context and overview', 'Legislative Decree - Mandate Period'),
  ('LD-1943-464', '1', 'Annulation des amendements constitutionnels', 'fr', 'Decision No. 464 Annulling the Constitutional Amendments, Article 1', 'Annulment of Constitutional Amendments', 'Legislative Decree - Mandate Period');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LD-1943-464', '1', 'إلغاء التعديلات الدستورية', 'ar', 'Decision No. 464 Annulling the Constitutional Amendments, Article 1', 'Annulment of Constitutional Amendments', 'Legislative Decree - Mandate Period'),
  ('LD-1943-464', '2', 'Dissolution de la Chambre des Députés', 'fr', 'Decision No. 464 Annulling the Constitutional Amendments, Article 2', 'Parliament Dissolution', 'Legislative Decree - Mandate Period'),
  ('LD-1943-464', '2', 'حل مجلس النواب', 'ar', 'Decision No. 464 Annulling the Constitutional Amendments, Article 2', 'Parliament Dissolution', 'Legislative Decree - Mandate Period'),
  ('LD-1943-464', NULL, 'French Mandate period - After Lebanese Parliament amended the Constitution on November 8, 1943 to remove articles contradicting independence, France retaliated with Decisions 464 and 465, annulling amendments, dissolving Parliament, and suspending the Constitution', 'en', 'Decision No. 464 Annulling the Constitutional Amendments — Historical Context', 'Historical context and overview', 'Legislative Decree - Mandate Period'),
  ('LD-1943-465', '1', 'Suspension de la Constitution', 'fr', 'Decision No. 465 Suspending the Constitution and Forming an Alternative Government, Article 1', 'Constitution Suspension', 'Legislative Decree - Mandate Period'),
  ('LD-1943-465', '1', 'تعليق العمل بالدستور', 'ar', 'Decision No. 465 Suspending the Constitution and Forming an Alternative Government, Article 1', 'Constitution Suspension', 'Legislative Decree - Mandate Period'),
  ('LD-1943-465', '2', 'Formation d''un gouvernement alternatif sous la présidence d''Emile Edde', 'fr', 'Decision No. 465 Suspending the Constitution and Forming an Alternative Government, Article 2', 'Alternative Government Formation', 'Legislative Decree - Mandate Period'),
  ('LD-1943-465', '2', 'تشكيل حكومة بديلة برئاسة إميل إده', 'ar', 'Decision No. 465 Suspending the Constitution and Forming an Alternative Government, Article 2', 'Alternative Government Formation', 'Legislative Decree - Mandate Period'),
  ('LD-1943-465', NULL, 'French Mandate period - French authorities arrested President Bechara el Khoury, Prime Minister Riad el Solh, and ministers on November 11, 1943, taking them to Rashaya citadel. This sparked national and international protests leading to independence on November 22, 1943', 'en', 'Decision No. 465 Suspending the Constitution and Forming an Alternative Government — Historical Context', 'Historical context and overview', 'Legislative Decree - Mandate Period'),
  ('LD-1943-INDEPENDENCE', '1', 'Libération du Président Bechara el Khoury, du Premier ministre Riad el Solh et des ministres détenus', 'fr', 'Independence of Lebanon - November 22, 1943, Article 1', 'Release of Detainees', 'Legislative Decree - Mandate Period'),
  ('LD-1943-INDEPENDENCE', '1', 'إطلاق سراح الرئيس بشارة الخوري ورئيس الوزراء رياض الصلح والوزراء المعتقلين', 'ar', 'Independence of Lebanon - November 22, 1943, Article 1', 'Release of Detainees', 'Legislative Decree - Mandate Period'),
  ('LD-1943-INDEPENDENCE', '2', 'Retour du gouvernement légitime à l''exercice de ses fonctions', 'fr', 'Independence of Lebanon - November 22, 1943, Article 2', 'Government Reinstatement', 'Legislative Decree - Mandate Period'),
  ('LD-1943-INDEPENDENCE', '2', 'عودة الحكومة الشرعية لممارسة مهامها', 'ar', 'Independence of Lebanon - November 22, 1943, Article 2', 'Government Reinstatement', 'Legislative Decree - Mandate Period'),
  ('LD-1943-INDEPENDENCE', '3', 'Retrait du drapeau français et hissage du drapeau libanais', 'fr', 'Independence of Lebanon - November 22, 1943, Article 3', 'Flag Change', 'Legislative Decree - Mandate Period'),
  ('LD-1943-INDEPENDENCE', '3', 'إنزال العلم الفرنسي ورفع العلم اللبناني', 'ar', 'Independence of Lebanon - November 22, 1943, Article 3', 'Flag Change', 'Legislative Decree - Mandate Period'),
  ('LD-1943-INDEPENDENCE', NULL, 'Independence - Under British and international pressure, General Catroux ordered the release of Lebanese leaders before noon on November 22, 1943. This day is celebrated as Lebanese Independence Day marking the end of the French Mandate.', 'en', 'Independence of Lebanon - November 22, 1943 — Historical Context', 'Historical context and overview', 'Legislative Decree - Mandate Period'),
  ('LD-1944-797K', '1', 'Le Ministère de la Justice se compose de la Direction et du Service des Affaires judiciaires et législatives', 'fr', 'Decree No. 797/K of March 6, 1944 on the First Regulation of the Ministry of Justice, Article 1', 'Ministry Structure', 'Legislative Decree - Mandate Period'),
  ('LD-1944-797K', '1', 'تتألف وزارة العدلية من المديرية ومصلحة الشؤون القضائية والتشريع', 'ar', 'Decree No. 797/K of March 6, 1944 on the First Regulation of the Ministry of Justice, Article 1', 'Ministry Structure', 'Legislative Decree - Mandate Period'),
  ('LD-1944-797K', '2', 'Création du Comité des Contentieux', 'fr', 'Decree No. 797/K of March 6, 1944 on the First Regulation of the Ministry of Justice, Article 2', 'Litigation Committee', 'Legislative Decree - Mandate Period'),
  ('LD-1944-797K', '2', 'إنشاء لجنة القضايا', 'ar', 'Decree No. 797/K of March 6, 1944 on the First Regulation of the Ministry of Justice, Article 2', 'Litigation Committee', 'Legislative Decree - Mandate Period'),
  ('LD-1944-797K', '3', 'Création du Service des Tribunaux religieux', 'fr', 'Decree No. 797/K of March 6, 1944 on the First Regulation of the Ministry of Justice, Article 3', 'Religious Courts Department', 'Legislative Decree - Mandate Period'),
  ('LD-1944-797K', '3', 'إنشاء مصلحة المحاكم الشرعية', 'ar', 'Decree No. 797/K of March 6, 1944 on the First Regulation of the Ministry of Justice, Article 3', 'Religious Courts Department', 'Legislative Decree - Mandate Period'),
  ('LD-1944-797K', NULL, 'Post-Independence - First regulation of the Ministry of Justice after independence, issued by the Lebanese government', 'en', 'Decree No. 797/K of March 6, 1944 on the First Regulation of the Ministry of Justice — Historical Context', 'Historical context and overview', 'Legislative Decree - Mandate Period'),
  ('LD-1920-LAND', '1', 'Création du Service du Cadastre', 'fr', 'Decree Establishing the Land Registry Service, Article 1', 'Land Registry Establishment', 'Legislative Decree - Mandate Period'),
  ('LD-1920-LAND', '1', 'إنشاء مصلحة السجل العقاري', 'ar', 'Decree Establishing the Land Registry Service, Article 1', 'Land Registry Establishment', 'Legislative Decree - Mandate Period'),
  ('LD-1920-LAND', '2', 'Transformation des terres communes en propriété privée', 'fr', 'Decree Establishing the Land Registry Service, Article 2', 'Land Transformation', 'Legislative Decree - Mandate Period'),
  ('LD-1920-LAND', '2', 'تحويل الأراضي المشاع إلى ملكية خاصة', 'ar', 'Decree Establishing the Land Registry Service, Article 2', 'Land Transformation', 'Legislative Decree - Mandate Period'),
  ('LD-1920-LAND', NULL, 'French Mandate period - The Régie de Travaux du Cadastre et d''Aménagement Foncière was established in 1920 to modernize land administration. By 1925, significant land concentration occurred in the Beqaa where nearly 78% of land was held by a small number of families.', 'en', 'Decree Establishing the Land Registry Service — Historical Context', 'Historical context and overview', 'Legislative Decree - Mandate Period'),
  ('LD-1930-RealProperty', '1', 'Régulation de la propriété immobilière au Liban', 'fr', 'Real Property Law 1930, Article 1', 'Real Property Regulation', 'Legislative Decree - Mandate Period'),
  ('LD-1930-RealProperty', '1', 'تنظيم الملكية العقارية في لبنان', 'ar', 'Real Property Law 1930, Article 1', 'Real Property Regulation', 'Legislative Decree - Mandate Period'),
  ('LD-1930-RealProperty', NULL, 'French Mandate period - The 1930 Real Property Law was a hybrid between Ottoman and French land regimes, further blurring the distinction between state domains and private holdings, enabling elite capture of land.', 'en', 'Real Property Law 1930 — Historical Context', 'Historical context and overview', 'Legislative Decree - Mandate Period'),
  ('LD-1983-150', '1', 'Organisation des tribunaux de première instance, d''appel et de la Cour de cassation', 'fr', 'Legislative Decree No. 150 of September 16, 1983 on Judicial Organization, Article 1', 'Court Organization', 'Legislative Decree - Post-Mandate'),
  ('LD-1983-150', '1', 'تنظيم المحاكم الابتدائية والاستئنافية ومحكمة التمييز', 'ar', 'Legislative Decree No. 150 of September 16, 1983 on Judicial Organization, Article 1', 'Court Organization', 'Legislative Decree - Post-Mandate'),
  ('LD-1983-150', '3', 'Les membres du Conseil supérieur de la magistrature sont responsables de préserver l''indépendance de la justice', 'fr', 'Legislative Decree No. 150 of September 16, 1983 on Judicial Organization, Article 3', 'Judicial Independence', 'Legislative Decree - Post-Mandate'),
  ('LD-1983-150', '3', 'أعضاء المجلس الأعلى للقضاء مسؤولون عن الحفاظ على استقلال القضاء', 'ar', 'Legislative Decree No. 150 of September 16, 1983 on Judicial Organization, Article 3', 'Judicial Independence', 'Legislative Decree - Post-Mandate'),
  ('LD-1983-150', '4', 'Indépendance des membres du Conseil supérieur de la magistrature', 'fr', 'Legislative Decree No. 150 of September 16, 1983 on Judicial Organization, Article 4', 'High Judicial Council Independence', 'Legislative Decree - Post-Mandate'),
  ('LD-1983-150', '4', 'استقلال أعضاء المجلس الأعلى للقضاء', 'ar', 'Legislative Decree No. 150 of September 16, 1983 on Judicial Organization, Article 4', 'High Judicial Council Independence', 'Legislative Decree - Post-Mandate'),
  ('LD-1983-150', NULL, 'Post-Mandate - Legislative Decree No. 150/1983 adopted the text of the Code of Judicial Organization issued in 1961, organizing the Court of Cassation and the State Council. It remains the primary law governing judicial organization in Lebanon today.', 'en', 'Legislative Decree No. 150 of September 16, 1983 on Judicial Organization — Historical Context', 'Historical context and overview', 'Legislative Decree - Post-Mandate'),
  ('LD-1975-10434', '1', 'Création du Conseil d''État', 'fr', 'Law No. 10434 of June 14, 1975 Establishing the State Council, Article 1', 'State Council Establishment', 'Legislative Decree - Post-Mandate'),
  ('LD-1975-10434', '1', 'إنشاء مجلس الدولة', 'ar', 'Law No. 10434 of June 14, 1975 Establishing the State Council, Article 1', 'State Council Establishment', 'Legislative Decree - Post-Mandate'),
  ('LD-1975-10434', '19', 'Les membres du Bureau du Conseil d''État sont responsables de préserver l''indépendance de l''institution', 'fr', 'Law No. 10434 of June 14, 1975 Establishing the State Council, Article 19', 'State Council Independence', 'Legislative Decree - Post-Mandate'),
  ('LD-1975-10434', '19', 'أعضاء مكتب مجلس الدولة مسؤولون عن الحفاظ على استقلال الهيئة', 'ar', 'Law No. 10434 of June 14, 1975 Establishing the State Council, Article 19', 'State Council Independence', 'Legislative Decree - Post-Mandate'),
  ('LD-1975-10434', NULL, 'Post-Mandate - Law enacted by decree No. 10434 of June 14, 1975 established the State Council as the supreme body for administrative jurisdiction, separating it from the Court of Cassation.', 'en', 'Law No. 10434 of June 14, 1975 Establishing the State Council — Historical Context', 'Historical context and overview', 'Legislative Decree - Post-Mandate'),
  ('LD-1951-ChristianPS', '1', 'Définition de la compétence des tribunaux confessionnels chrétiens et israélites', 'fr', 'Law of April 2, 1951 on Personal Status of Christian and Israelite Communities, Article 1', 'Christian Religious Courts Jurisdiction', 'Legislative Decree - Post-Mandate'),
  ('LD-1951-ChristianPS', '1', 'تحديد اختصاص المحاكم الطائفية المسيحية والإسرائيلية', 'ar', 'Law of April 2, 1951 on Personal Status of Christian and Israelite Communities, Article 1', 'Christian Religious Courts Jurisdiction', 'Legislative Decree - Post-Mandate'),
  ('LD-1951-ChristianPS', '33', 'Les communautés doivent soumettre leur code de statut personnel et leur code de procédure des tribunaux religieux dans un délai d''un an', 'fr', 'Law of April 2, 1951 on Personal Status of Christian and Israelite Communities, Article 33', 'Sects Must Submit Personal Status Codes', 'Legislative Decree - Post-Mandate'),
  ('LD-1951-ChristianPS', '33', 'على الطوائف تقديم قانون الأحوال الشخصية وقانون إجراءات محاكمها الدينية خلال سنة', 'ar', 'Law of April 2, 1951 on Personal Status of Christian and Israelite Communities, Article 33', 'Sects Must Submit Personal Status Codes', 'Legislative Decree - Post-Mandate'),
  ('LD-1951-ChristianPS', NULL, 'Post-Mandate - Following the expansion of Sunni and Jafari religious courts jurisdiction by Legislative Decree 6/1930, this law expanded Christian religious courts jurisdiction to be on par with Islamic courts, sparking protests from the Bar Association.', 'en', 'Law of April 2, 1951 on Personal Status of Christian and Israelite Communities — Historical Context', 'Historical context and overview', 'Legislative Decree - Post-Mandate'),
  ('LD-1942-SunniShia', '1', 'Organisation des tribunaux religieux sunnites et jaafarites', 'fr', 'Articles on Sunni and Jafari Religious Courts from Legislative Decree No. 6, Article 1', 'Sunni and Jafari Courts Organization', 'Legislative Decree - Mandate Period'),
  ('LD-1942-SunniShia', '1', 'تنظيم المحاكم الشرعية السنية والجعفرية', 'ar', 'Articles on Sunni and Jafari Religious Courts from Legislative Decree No. 6, Article 1', 'Sunni and Jafari Courts Organization', 'Legislative Decree - Mandate Period');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LD-1942-SunniShia', NULL, 'French Mandate period - Legislative Decree 6/1930 organized Sunni and Jafari religious courts, granting them jurisdiction over personal status matters for Muslim communities. Later modified by Law 16/07/1962.', 'en', 'Articles on Sunni and Jafari Religious Courts from Legislative Decree No. 6 — Historical Context', 'Historical context and overview', 'Legislative Decree - Mandate Period'),
  ('LD-1935-126', '1', 'Application du Code de justice militaire française en Syrie et au Liban', 'fr', 'Legislative Decree No. 126 of May 30, 1935 on Military Justice, Article 1', 'French Military Penal Code Application', 'Legislative Decree - Mandate Period'),
  ('LD-1935-126', '1', 'تطبيق القانون العقوبي العسكري الفرنسي في سوريا ولبنان', 'ar', 'Legislative Decree No. 126 of May 30, 1935 on Military Justice, Article 1', 'French Military Penal Code Application', 'Legislative Decree - Mandate Period'),
  ('LD-1935-126', NULL, 'French Mandate period - Legislative Decree No. 126 of May 30, 1935 applied the French Military Penal Code in Syria and Lebanon, replacing Ottoman military laws. This code continued in force even after the mandate ended until amended by Legislative Decree No. 15/1949 and replaced by Law 61/1950.', 'en', 'Legislative Decree No. 126 of May 30, 1935 on Military Justice — Historical Context', 'Historical context and overview', 'Legislative Decree - Mandate Period'),
  ('LD-1918-OPC', '534', 'Article criminalisant les pratiques homosexuelles (probablement d''origine jésuite-marronite plutôt que coloniale)', 'fr', 'Ottoman Penal Code Amended (in force until 1943), Article 534', 'Article 534 on Homosexuality', 'Legislative Decree - Mandate Period'),
  ('LD-1918-OPC', '534', 'مادة تجرم الممارسات المثلية (المحتمل أنها من التراث اليسوعي-الماروني وليس الاستعماري)', 'ar', 'Ottoman Penal Code Amended (in force until 1943), Article 534', 'Article 534 on Homosexuality', 'Legislative Decree - Mandate Period'),
  ('LD-1918-OPC', NULL, 'French Mandate period - The Ottoman Penal Code continued in force during the French Mandate with amendments. Article 534 criminalizing homosexual practices is often mistakenly attributed to the French Mandate, but research suggests it was influenced by Jesuit-Maronite moral theology rather than French colonial law, as French penal codes had not criminalized same-sex relations since 1791.', 'en', 'Ottoman Penal Code Amended (in force until 1943) — Historical Context', 'Historical context and overview', 'Legislative Decree - Mandate Period'),
  ('LD-1943-1109', '1', 'Le Liban est un État indépendant, indivisible et souverain', 'fr', 'Constitutional Law of November 9, 1943, Article 1', 'Independence Declaration', 'Legislative Decree - Mandate Period'),
  ('LD-1943-1109', '1', 'لبنان دولة مستقلة، لا تتجزأ، ذات سيادة', 'ar', 'Constitutional Law of November 9, 1943, Article 1', 'Independence Declaration', 'Legislative Decree - Mandate Period'),
  ('LD-1943-1109', '5', 'Définition du drapeau libanais: trois bandes horizontales, blanche entre deux rouges, cèdre vert au centre', 'fr', 'Constitutional Law of November 9, 1943, Article 5', 'Lebanese Flag Definition', 'Legislative Decree - Mandate Period'),
  ('LD-1943-1109', '5', 'تحديد علم لبنان: ثلاثة أشرطة أفقية، أبيض بين أحمرين، أرز أخضر في الوسط', 'ar', 'Constitutional Law of November 9, 1943, Article 5', 'Lebanese Flag Definition', 'Legislative Decree - Mandate Period'),
  ('LD-1943-1109', '90-94', 'Abrogation des articles relatifs au mandat et à la Société des Nations', 'fr', 'Constitutional Law of November 9, 1943, Article 90-94', 'Mandate Articles Abolition', 'Legislative Decree - Mandate Period'),
  ('LD-1943-1109', '90-94', 'إلغاء المواد المتعلقة بالانتداب والعصبة الأمم', 'ar', 'Constitutional Law of November 9, 1943, Article 90-94', 'Mandate Articles Abolition', 'Legislative Decree - Mandate Period'),
  ('LD-1943-1109', NULL, 'Independence - Constitutional amendments adopted on November 8, 1943 by Parliament removed all references to the French Mandate from the Constitution. France responded with Decisions 464 and 465, but under international pressure, recognized independence on November 22, 1943.', 'en', 'Constitutional Law of November 9, 1943 — Historical Context', 'Historical context and overview', 'Legislative Decree - Mandate Period'),
  ('LD-1959-CivilService', '1', 'Organisation du Ministère de la Justice', 'fr', 'Legislative Decree No. 111 of June 12, 1959 Organizing the Ministry of Justice, Article 1', 'Ministry of Justice Organization', 'Legislative Decree - Post-Mandate'),
  ('LD-1959-CivilService', '1', 'تنظيم وزارة العدل', 'ar', 'Legislative Decree No. 111 of June 12, 1959 Organizing the Ministry of Justice, Article 1', 'Ministry of Justice Organization', 'Legislative Decree - Post-Mandate'),
  ('LD-1959-CivilService', NULL, 'Post-Mandate - Legislative Decree No. 111/1959 organized the Ministry of Justice. This was part of the legislative reforms during President Fouad Chehab''s mandate (1958-1964), which included the Civil Service Law and Judiciary Organization laws.', 'en', 'Legislative Decree No. 111 of June 12, 1959 Organizing the Ministry of Justice — Historical Context', 'Historical context and overview', 'Legislative Decree - Post-Mandate'),
  ('LD-1943-NationalPact', '1', 'Le Président de la République est de confession maronite', 'fr', 'National Pact 1943, Article 1', 'President - Maronite', 'Legislative Decree - Mandate Period'),
  ('LD-1943-NationalPact', '1', 'الرئيس جمهورية من الطائفة المارونية', 'ar', 'National Pact 1943, Article 1', 'President - Maronite', 'Legislative Decree - Mandate Period'),
  ('LD-1943-NationalPact', '2', 'Le Premier ministre est de confession sunnite', 'fr', 'National Pact 1943, Article 2', 'Prime Minister - Sunni', 'Legislative Decree - Mandate Period'),
  ('LD-1943-NationalPact', '2', 'رئيس الوزراء من الطائفة السنية', 'ar', 'National Pact 1943, Article 2', 'Prime Minister - Sunni', 'Legislative Decree - Mandate Period'),
  ('LD-1943-NationalPact', '3', 'Le Président de la Chambre des Députés est de confession chiite', 'fr', 'National Pact 1943, Article 3', 'Speaker - Shia', 'Legislative Decree - Mandate Period'),
  ('LD-1943-NationalPact', '3', 'رئيس مجلس النواب من الطائفة الشيعية', 'ar', 'National Pact 1943, Article 3', 'Speaker - Shia', 'Legislative Decree - Mandate Period'),
  ('LD-1943-NationalPact', '4', 'Répartition confessionnelle des députés 6 chrétiens pour 5 musulmans', 'fr', 'National Pact 1943, Article 4', 'Parliamentary Representation', 'Legislative Decree - Mandate Period'),
  ('LD-1943-NationalPact', '4', 'التوزيع الطائفي للنواب 6 مسيحيين مقابل 5 مسلمين', 'ar', 'National Pact 1943, Article 4', 'Parliamentary Representation', 'Legislative Decree - Mandate Period'),
  ('LD-1943-NationalPact', NULL, 'Independence - The National Pact was an unwritten agreement adopted around September 25, 1943 between Christian and Muslim leaders. It established the confessional power-sharing formula: President (Maronite), Prime Minister (Sunni), Speaker (Shia), and 6:5 Christian-Muslim ratio in Parliament. It was based on the 1932 census showing Christians as slight majority.', 'en', 'National Pact 1943 — Historical Context', 'Historical context and overview', 'Legislative Decree - Mandate Period'),
  ('LD-1989-Taif', '24', 'Égalité entre chrétiens et musulmans dans la Chambre des Députés', 'fr', 'Taif Agreement - Constitutional Law of September 21, 1990, Article 24', 'Equal Parliamentary Representation', 'Legislative Decree - Post-Mandate'),
  ('LD-1989-Taif', '24', 'المساواة بين المسيحيين والمسلمين في المجلس النيابي', 'ar', 'Taif Agreement - Constitutional Law of September 21, 1990, Article 24', 'Equal Parliamentary Representation', 'Legislative Decree - Post-Mandate'),
  ('LD-1989-Taif', '65', 'Renforcement des pouvoirs du Conseil des Ministres par rapport au Président de la République', 'fr', 'Taif Agreement - Constitutional Law of September 21, 1990, Article 65', 'Powers Redistribution', 'Legislative Decree - Post-Mandate'),
  ('LD-1989-Taif', '65', 'زيادة صلاحيات مجلس الوزراء مقابل صلاحيات رئيس الجمهورية', 'ar', 'Taif Agreement - Constitutional Law of September 21, 1990, Article 65', 'Powers Redistribution', 'Legislative Decree - Post-Mandate'),
  ('LD-1989-Taif', '95', 'Abolition progressive du confessionnalisme politique', 'fr', 'Taif Agreement - Constitutional Law of September 21, 1990, Article 95', 'Abolition of Political Confessionalism', 'Legislative Decree - Post-Mandate'),
  ('LD-1989-Taif', '95', 'إلغاء الطائفية السياسية تدريجياً', 'ar', 'Taif Agreement - Constitutional Law of September 21, 1990, Article 95', 'Abolition of Political Confessionalism', 'Legislative Decree - Post-Mandate'),
  ('LD-1989-Taif', NULL, 'Post-Mandate - The Taif Agreement was signed on October 22, 1989 in Taif, Saudi Arabia to end the Lebanese Civil War (1975-1990). It amended the Constitution to provide equal representation between Christians and Muslims in Parliament (previously 6:5), strengthened the Council of Ministers at the expense of the President, and called for gradual abolition of political confessionalism.', 'en', 'Taif Agreement - Constitutional Law of September 21, 1990 — Historical Context', 'Historical context and overview', 'Legislative Decree - Post-Mandate'),
  ('LB-LD-001', NULL, 'Trademark registration and protection system. One of the oldest still-enforced laws.', 'en', 'Trademarks and Trade Names — Historical Context', 'Historical context and overview', 'Commercial Law'),
  ('LB-LD-002', NULL, 'Modern property registration (Torrens) system replacing Ottoman land categories.', 'en', 'Real Property Law — Historical Context', 'Historical context and overview', 'Civil Law'),
  ('LB-LD-003', NULL, 'Primary civil law code. See civil_code.json for full entry.', 'en', 'Code of Obligations and Contracts — Historical Context', 'Historical context and overview', 'Civil Law'),
  ('LB-LD-004', NULL, 'Water rights and concessions. Foundation of Lebanese water law.', 'en', 'Water Law — Historical Context', 'Historical context and overview', 'Administrative & Municipal'),
  ('LB-LD-005', NULL, 'Forest protection and management. One of the earliest environmental protection laws.', 'en', 'Forests Law — Historical Context', 'Historical context and overview', 'Environmental'),
  ('LB-LD-006', NULL, 'Governs print media, press freedom, journalist protections, and publication licensing.', 'en', 'Press and Publications Law — Historical Context', 'Historical context and overview', 'Media & Press'),
  ('LB-LD-007', NULL, 'Regulates foreign ownership of real property in Lebanon. Restricts foreign ownership based on area limits and requires prior approval.', 'en', 'Acquisition of Real Property by Foreigners — Historical Context', 'Historical context and overview', 'Property & Real Estate'),
  ('LB-LD-008', NULL, 'See penal_code.json for full entry.', 'en', 'Penal Code — Historical Context', 'Historical context and overview', 'Criminal Law'),
  ('LB-LD-009', NULL, 'See commercial_code.json for full entry.', 'en', 'Code of Terrestrial Commerce — Historical Context', 'Historical context and overview', 'Commercial Law'),
  ('LB-LD-010', NULL, 'First electoral law for the Representative Council. Established confessional seat allocation.', 'en', 'Electoral Law (First) — Historical Context', 'Historical context and overview', 'Electoral Law'),
  ('LB-LD-011', NULL, 'Public accounting and government financial management rules.', 'en', 'Government Accounting Law — Historical Context', 'Historical context and overview', 'Tax & Fiscal'),
  ('LB-LD-012', NULL, 'Land surveying and cadastral registration system.', 'en', 'Land Registration Law — Historical Context', 'Historical context and overview', 'Property & Real Estate'),
  ('LB-LD-013', NULL, 'Penal code for military offenses and military court jurisdiction.', 'en', 'Military Penal Code — Historical Context', 'Historical context and overview', 'Military & Security'),
  ('LB-LD-014', NULL, 'Established the administrative court system (Conseil d''État / مجلس شورى الدولة).', 'en', 'Organization of the Conseil d''État — Historical Context', 'Historical context and overview', 'Judicial Organization'),
  ('LB-LD-015', NULL, 'Foundation of Lebanese nationality law. Established who qualifies as Lebanese. Controversially, nationality passes primarily through the father (patrilineal system). Decades-long campaign for women to pass nationality to their children has not yet succeeded.', 'en', 'Lebanese Nationality Law — Historical Context', 'Historical context and overview', 'Civil Law'),
  ('LB-MUN-001', NULL, 'Primary law governing Lebanon''s 1,064 municipalities. Enacted during the early civil war period. Defines municipal powers, elections, budgets, and relationship with central government. Article 16 states that parliamentary election provisions apply to municipal elections. Municipal elections are held separately from parliamentary elections. Municipalities manage local affairs including urban planning, waste management, local roads, and public spaces. Lebanon also has 51 municipal unions (federations of municipalities).', 'en', 'Municipal Act / Municipalities Law — Historical Context', 'Historical context and overview', 'Administrative & Municipal'),
  ('LB-MUN-001', NULL, 'Major amendments to the Municipal Act. Key reform of municipal governance and elections.', 'en', 'Municipal Act / Municipalities Law — Amendment: Law No. 665/1997', 'Amendment', 'Administrative & Municipal');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-MUN-002', NULL, 'Governs the office of moukhtar (مختار), the elected neighborhood/village chief. Lebanon has 3,018 moukhtars who serve as local administrative officials handling personal status documentation, attestations, and acting as intermediaries between citizens and government agencies.', 'en', 'Moukhtar (Village/Neighborhood Chief) Law — Historical Context', 'Historical context and overview', 'Administrative & Municipal'),
  ('LB-ELECT-001', NULL, 'Replaced Electoral Law No. 25/2008. Landmark reform: introduced proportional representation for the first time in Lebanese history (replacing winner-takes-all majoritarian system). Key features: 15 electoral districts, preferential voting within party lists, diaspora voting provisions (Article 3), establishment of Supervisory Commission for Elections, campaign finance regulations including lifting banking secrecy for campaign accounts. The law was used for the 2018 and 2022 parliamentary elections. Previous electoral laws: Law 25/2008, Law 171/2000, Law of 1960.', 'en', 'Parliamentary Elections Law — Historical Context', 'Historical context and overview', 'Electoral Law'),
  ('LB-ELECT-001', '84, 112, 122', 'Suspended biometric voting card (Art. 84) and diaspora constituency (Arts. 112, 122) for 2022 elections on exceptional one-time basis. Rescheduled election date.', 'en', 'Parliamentary Elections Law — Amendment: Amendments of October 19, 2021', 'Amendment', 'Electoral Law'),
  ('LB-MUN-003', NULL, 'Governs building permits, construction standards, zoning, and urban planning regulations. Administered by the Directorate General of Urban Planning (DGU) and the Order of Engineers and Architects. Post-war reconstruction generated significant construction activity, making this law particularly important.', 'en', 'Building/Construction Law — Historical Context', 'Historical context and overview', 'Administrative & Municipal'),
  ('LB-MUN-003', NULL, 'Comprehensive amendments to building regulations and permits.', 'en', 'Building/Construction Law — Amendment: Law No. 646/2004 (Amended Construction Law)', 'Amendment', 'Administrative & Municipal'),
  ('LB-MUN-004', NULL, 'Lebanon''s primary environmental legislation. Established the Ministry of Environment''s mandate, environmental impact assessment requirements, pollution control standards, and nature protection provisions. Implementation has been criticized as weak due to institutional capacity constraints.', 'en', 'Environmental Protection Law — Historical Context', 'Historical context and overview', 'Environmental'),
  ('LB-MUN-005', NULL, 'Established the CDR as the primary government body for physical infrastructure reconstruction and development project management. Originally created in 1977 for post-war reconstruction, it became the main conduit for international development funding to Lebanon.', 'en', 'Council for Development and Reconstruction (CDR) Law — Historical Context', 'Historical context and overview', 'Administrative & Municipal'),
  ('LB-MUN-006', NULL, 'Landmark transparency legislation granting citizens the right to access information held by government entities. Requires proactive publication of certain categories of information. Establishes procedures for information requests and exemptions. Implementation has been gradual, with the National Anti-Corruption Commission taking on oversight responsibilities.', 'en', 'Right to Access Information Law — Historical Context', 'Historical context and overview', 'Administrative & Municipal'),
  ('LB-MUN-007', NULL, 'Established the National Anti-Corruption Commission (NACC) and criminalized corruption in the public sector. Part of a package of reform laws demanded by the international community. The NACC was eventually formed in 2022 after delays in appointing commissioners.', 'en', 'Anti-Corruption in the Public Sector and Establishment of the National Anti-Corruption Commission Law — Historical Context', 'Historical context and overview', 'Administrative & Municipal'),
  ('LB-MUN-008', NULL, 'Provides legal protections for individuals who report corruption in the public and private sectors. Covers protection from retaliation, confidentiality guarantees, and procedures for reporting.', 'en', 'Whistleblower Protection Law — Historical Context', 'Historical context and overview', 'Administrative & Municipal'),
  ('LB-MUN-009', NULL, 'One of the oldest still-operative laws in Lebanon, dating from the Ottoman period (1909). Governs the formation and operation of non-profit associations, clubs, and civil society organizations. Requires notification (ilm wa khabar) to the Ministry of Interior for formation. Despite its age, the law provides a relatively permissive framework for civil society. Decree 2791/1959 supplemented Ottoman-era provisions. The law also governs political parties, which has been criticized as outdated.', 'en', 'Law of Associations — Historical Context', 'Historical context and overview', 'Administrative & Municipal'),
  ('LEB-MUN-001', 'Article 1', 'La municipalité est une administration locale qui exerce, sur son territoire, les prérogatives qui lui sont accordées par la loi. Elle est dotée de la personnalité morale et jouit de l''autonomie financière et administrative.', 'fr', 'Municipal Act - Decree-Law No. 118 dated June 30, 1977, Article Article 1', 'Definition and legal personality of municipalities', 'Municipal Law'),
  ('LEB-MUN-001', 'Article 1', 'البلدية هي إدارة محلية تمارس ضمن نطاق عملها الصلاحيات المخولة إليها بموجب القانون. تتمتع البلدية بالشخصية المعنوية والاستقلال المالي والإداري.', 'ar', 'Municipal Act - Decree-Law No. 118 dated June 30, 1977, Article Article 1', 'Definition and legal personality of municipalities', 'Municipal Law'),
  ('LEB-MUN-001', 'Article 7', 'Le Conseil municipal détient l''autorité décisionnelle.', 'fr', 'Municipal Act - Decree-Law No. 118 dated June 30, 1977, Article Article 7', 'Municipal Council as decision-making authority', 'Municipal Law'),
  ('LEB-MUN-001', 'Article 7', 'يقوم مجلس البلدية بالسلطة المقررة.', 'ar', 'Municipal Act - Decree-Law No. 118 dated June 30, 1977, Article Article 7', 'Municipal Council as decision-making authority', 'Municipal Law'),
  ('LEB-MUN-001', 'Article 9', 'Le Conseil municipal se compose d''un nombre de membres déterminé selon la population.', 'fr', 'Municipal Act - Decree-Law No. 118 dated June 30, 1977, Article Article 9', 'Composition of Municipal Council based on population', 'Municipal Law'),
  ('LEB-MUN-001', 'Article 9', 'يتركب مجلس البلدية من عدد من الأعضاء يتحدد بحسب عدد السكان.', 'ar', 'Municipal Act - Decree-Law No. 118 dated June 30, 1977, Article Article 9', 'Composition of Municipal Council based on population', 'Municipal Law'),
  ('LEB-MUN-001', 'Article 47', 'La municipalité est compétente pour toute activité publique ou d''utilité publique dans les limites de son territoire.', 'fr', 'Municipal Act - Decree-Law No. 118 dated June 30, 1977, Article Article 47', 'Municipal competencies and powers', 'Municipal Law'),
  ('LEB-MUN-001', 'Article 47', 'تختص البلدية بكل عمل من أعمال الصفة العامة أو المنفعة العامة في حدود نطاقها.', 'ar', 'Municipal Act - Decree-Law No. 118 dated June 30, 1977, Article Article 47', 'Municipal competencies and powers', 'Municipal Law'),
  ('LEB-MUN-001', 'Article 49', 'Le Conseil municipal est chargé d''établir et d''adopter le budget annuel de la municipalité et de déterminer les taxes et redevances.', 'fr', 'Municipal Act - Decree-Law No. 118 dated June 30, 1977, Article Article 49', 'Municipal Council financial powers', 'Municipal Law'),
  ('LEB-MUN-001', 'Article 49', 'يختص مجلس البلدية بوضع وإقرار ميزانية البلدية السنوية وتحديد الرسوم والضرائب.', 'ar', 'Municipal Act - Decree-Law No. 118 dated June 30, 1977, Article Article 49', 'Municipal Council financial powers', 'Municipal Law'),
  ('LEB-MUN-001', 'Article 67', 'L''autorité exécutive dans la municipalité est le Président du Conseil municipal, et dans la municipalité de Beyrouth, c''est le Gouverneur.', 'fr', 'Municipal Act - Decree-Law No. 118 dated June 30, 1977, Article Article 67', 'Executive authority in municipalities', 'Municipal Law'),
  ('LEB-MUN-001', 'Article 67', 'تختص السلطة التنفيذية في البلدية برئيس مجلس البلدية، وفي بلدية بيروت تختص بالمحافظ.', 'ar', 'Municipal Act - Decree-Law No. 118 dated June 30, 1977, Article Article 67', 'Executive authority in municipalities', 'Municipal Law'),
  ('LEB-MUN-001', 'Article 86', 'Les finances municipales se composent des taxes directes, des taxes collectées par l''État, des aides financières et des prêts.', 'fr', 'Municipal Act - Decree-Law No. 118 dated June 30, 1977, Article Article 86', 'Municipal finances composition', 'Municipal Law'),
  ('LEB-MUN-001', 'Article 86', 'تتألف موارد البلدية من الرسوم المباشرة والرسوم المحصلة من الدولة والمساعدات المالية والقروض.', 'ar', 'Municipal Act - Decree-Law No. 118 dated June 30, 1977, Article Article 86', 'Municipal finances composition', 'Municipal Law'),
  ('LEB-MUN-001', NULL, 'The Municipal Law was enacted during the Lebanese Civil War (1975-1990) as a framework for local governance. It replaced previous Ottoman and French Mandate-era municipal legislation. The law established the foundation for municipal autonomy while maintaining central government oversight. It was significantly amended by Law 665/1997 to update electoral procedures and municipal governance structures.', 'en', 'Municipal Act - Decree-Law No. 118 dated June 30, 1977 — Historical Context', 'Historical context and overview', 'Municipal Law'),
  ('LEB-URB-001', 'Article 4-17', 'Les dispositions relatives à l''urbanisme se concentrent sur les plans, règlements et conditions de planification.', 'fr', 'Urban Planning Code - Decree-Law No. 69 dated September 9, 1983, Article Article 4-17', 'Urban planning - plans and regulations', 'Urban Planning Law'),
  ('LEB-URB-001', 'Article 4-17', 'أحكام التنظيم المدني تركز على المخططات والأنظمة وشروط التخطيط.', 'ar', 'Urban Planning Code - Decree-Law No. 69 dated September 9, 1983, Article Article 4-17', 'Urban planning - plans and regulations', 'Urban Planning Law'),
  ('LEB-URB-001', 'Article 11', 'Les plans d''urbanisme et règlements sont soumis aux municipalités concernées pour avis dans un délai d''un mois.', 'fr', 'Urban Planning Code - Decree-Law No. 69 dated September 9, 1983, Article Article 11', 'Municipal consultation on urban plans', 'Urban Planning Law'),
  ('LEB-URB-001', 'Article 11', 'تقدم المخططات التنظيمية والأنظمة إلى البلديات المعنية لإبداء الرأي خلال مدة شهر واحد.', 'ar', 'Urban Planning Code - Decree-Law No. 69 dated September 9, 1983, Article Article 11', 'Municipal consultation on urban plans', 'Urban Planning Law'),
  ('LEB-URB-001', 'Article 17', 'Le coefficient d''exploitation des terrains privés situés dans la zone côtière peut être réduit.', 'fr', 'Urban Planning Code - Decree-Law No. 69 dated September 9, 1983, Article Article 17', 'Coastal zone development restrictions', 'Urban Planning Law'),
  ('LEB-URB-001', 'Article 17', 'يمكن تخفيض معامل استثمار الأراضي الخاصة الواقعة في المنطقة الساحلية.', 'ar', 'Urban Planning Code - Decree-Law No. 69 dated September 9, 1983, Article Article 17', 'Coastal zone development restrictions', 'Urban Planning Law'),
  ('LEB-URB-001', 'Article 18-24', 'Les opérations d''aménagement et les arrangements opérationnels que le gouvernement peut utiliser lors de la réalisation d''un projet de développement.', 'fr', 'Urban Planning Code - Decree-Law No. 69 dated September 9, 1983, Article Article 18-24', 'Urban planning operations', 'Urban Planning Law'),
  ('LEB-URB-001', 'Article 18-24', 'عمليات التعمير والترتيبات التشغيلية التي يمكن للحكومة استخدامها عند تنفيذ مشروع تنموي.', 'ar', 'Urban Planning Code - Decree-Law No. 69 dated September 9, 1983, Article Article 18-24', 'Urban planning operations', 'Urban Planning Law'),
  ('LEB-URB-001', 'Article 21', 'Les sociétés immobilières peuvent être constituées par décret ministériel.', 'fr', 'Urban Planning Code - Decree-Law No. 69 dated September 9, 1983, Article Article 21', 'Real estate companies for development', 'Urban Planning Law'),
  ('LEB-URB-001', 'Article 21', 'الشركات العقارية يمكن تأسيسها بموجب مرسوم وزاري.', 'ar', 'Urban Planning Code - Decree-Law No. 69 dated September 9, 1983, Article Article 21', 'Real estate companies for development', 'Urban Planning Law'),
  ('LEB-URB-001', 'Article 25-44', 'Les permis de construire et le lotissement des terrains.', 'fr', 'Urban Planning Code - Decree-Law No. 69 dated September 9, 1983, Article Article 25-44', 'Building permits and land subdivision', 'Urban Planning Law'),
  ('LEB-URB-001', 'Article 25-44', 'تراخيص البناء وتقسيم الأراضي.', 'ar', 'Urban Planning Code - Decree-Law No. 69 dated September 9, 1983, Article Article 25-44', 'Building permits and land subdivision', 'Urban Planning Law'),
  ('LEB-URB-001', NULL, 'The Urban Planning Code was enacted during the Lebanese Civil War to modernize urban planning regulations. It established the framework for master plans, building permits, and land subdivision. The law created mechanisms for large-scale development projects including the establishment of real estate companies like SOLIDERE for Beirut city center reconstruction.', 'en', 'Urban Planning Code - Decree-Law No. 69 dated September 9, 1983 — Historical Context', 'Historical context and overview', 'Urban Planning Law'),
  ('LEB-ENV-001', 'Article 1', 'Cette loi vise à protéger l''environnement et à réaliser le développement durable.', 'fr', 'Environmental Protection Law - Law No. 444 dated July 29, 2002, Article Article 1', 'Purpose of the law', 'Environmental Law'),
  ('LEB-ENV-001', 'Article 1', 'يهدف هذا القانون إلى حماية البيئة وتحقيق التنمية المستدامة.', 'ar', 'Environmental Protection Law - Law No. 444 dated July 29, 2002, Article Article 1', 'Purpose of the law', 'Environmental Law'),
  ('LEB-ENV-001', 'Article 24', 'Il est interdit à toute personne physique ou morale de causer toute émission ou fuite de polluant dans l''environnement.', 'fr', 'Environmental Protection Law - Law No. 444 dated July 29, 2002, Article Article 24', 'Prohibition of pollution emissions', 'Environmental Law'),
  ('LEB-ENV-001', 'Article 24', 'يحظر على أي شخص طبيعي أو معنوي إحداث أي انبعاث أو تسرب لأي ملوث إلى البيئة.', 'ar', 'Environmental Protection Law - Law No. 444 dated July 29, 2002, Article Article 24', 'Prohibition of pollution emissions', 'Environmental Law'),
  ('LEB-ENV-001', 'Article 25', 'Les émissions résultant de la combustion de carburant doivent rester dans les limites autorisées.', 'fr', 'Environmental Protection Law - Law No. 444 dated July 29, 2002, Article Article 25', 'Emission limits', 'Environmental Law'),
  ('LEB-ENV-001', 'Article 25', 'يجب أن تبقى الانبعاثات الناتجة عن حرق الوقود ضمن الحدود المسموح بها.', 'ar', 'Environmental Protection Law - Law No. 444 dated July 29, 2002, Article Article 25', 'Emission limits', 'Environmental Law'),
  ('LEB-ENV-001', 'Section V', 'Protection des ressources environnementales - Chapitre Ier concerne la protection de la qualité de l''air et le contrôle des odeurs désagréables.', 'fr', 'Environmental Protection Law - Law No. 444 dated July 29, 2002, Article Section V', 'Air quality protection', 'Environmental Law'),
  ('LEB-ENV-001', 'Section V', 'حماية الموارد البيئية - الفصل الأول يتعلق بحماية جودة الهواء ومراقبة الروائح الكريهة.', 'ar', 'Environmental Protection Law - Law No. 444 dated July 29, 2002, Article Section V', 'Air quality protection', 'Environmental Law'),
  ('LEB-ENV-001', 'EIA Provisions', 'L''évaluation environnementale des grands projets est obligatoire.', 'fr', 'Environmental Protection Law - Law No. 444 dated July 29, 2002, Article EIA Provisions', 'Environmental Impact Assessment requirement', 'Environmental Law'),
  ('LEB-ENV-001', 'EIA Provisions', 'التقييم البيئي للمشاريع الكبرى إلزامي.', 'ar', 'Environmental Protection Law - Law No. 444 dated July 29, 2002, Article EIA Provisions', 'Environmental Impact Assessment requirement', 'Environmental Law'),
  ('LEB-ENV-001', NULL, 'Law 444/2002 is Lebanon''s overarching environmental protection legislation, enacted to align with international environmental conventions. It established the framework for Environmental Impact Assessments (EIA) and Strategic Environmental Assessments (SEA) through subsequent decrees. The law reflects principles from international treaties including the polluter-pays principle, precautionary principle, and public participation.', 'en', 'Environmental Protection Law - Law No. 444 dated July 29, 2002 — Historical Context', 'Historical context and overview', 'Environmental Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LEB-CON-001', 'Article 7', 'Assurer un éclairage naturel suffisant dans les bâtiments.', 'fr', 'Construction Law / Building Code - Law No. 646 of 2004, Article Article 7', 'Daylighting requirements', 'Construction Law'),
  ('LEB-CON-001', 'Article 7', 'التأكد من توفير الإضاءة الطبيعية الكافية في المباني.', 'ar', 'Construction Law / Building Code - Law No. 646 of 2004, Article Article 7', 'Daylighting requirements', 'Construction Law'),
  ('LEB-CON-001', 'Article 14', 'Le coefficient d''exploitation surfacique est le rapport entre la surface de projection horizontale du bâtiment et la surface du terrain.', 'fr', 'Construction Law / Building Code - Law No. 646 of 2004, Article Article 14', 'Investment factor / FAR definition', 'Construction Law'),
  ('LEB-CON-001', 'Article 14', 'معامل الاستثمار السطحي هو النسبة بين مساحة الإسقاط الأفقي للبناء ومساحة الأرض.', 'ar', 'Construction Law / Building Code - Law No. 646 of 2004, Article Article 14', 'Investment factor / FAR definition', 'Construction Law'),
  ('LEB-CON-001', 'Double Wall Provision', 'En cas de mur double, les surfaces des murs extérieurs ne sont pas comptées dans le coefficient d''exploitation.', 'fr', 'Construction Law / Building Code - Law No. 646 of 2004, Article Double Wall Provision', 'Double wall provision for energy efficiency', 'Construction Law'),
  ('LEB-CON-001', 'Double Wall Provision', 'في حالة الجدار المزدوج، لا تحتسب مساحات الجدران الخارجية ضمن معامل الاستثمار.', 'ar', 'Construction Law / Building Code - Law No. 646 of 2004, Article Double Wall Provision', 'Double wall provision for energy efficiency', 'Construction Law'),
  ('LEB-CON-001', 'Environmental Easements', 'Imposition de servitudes environnementales spécifiques en plus de la conformité avec la Loi 444/2002 sur la protection de l''environnement.', 'fr', 'Construction Law / Building Code - Law No. 646 of 2004, Article Environmental Easements', 'Environmental protection during construction', 'Construction Law'),
  ('LEB-CON-001', 'Environmental Easements', 'فرض قيادات بيئية خاصة بالإضافة إلى الالتزام بأحكام قانون حماية البيئة رقم 444/2002.', 'ar', 'Construction Law / Building Code - Law No. 646 of 2004, Article Environmental Easements', 'Environmental protection during construction', 'Construction Law'),
  ('LEB-CON-001', NULL, 'The Construction Law 646/2004 replaced older building regulations and introduced modern construction standards. It includes provisions for environmental protection during construction, building envelope ratios, and exploitation factors. The law was implemented through decrees in 2005 and 2007. It is the centerpiece of all construction activities in Lebanon.', 'en', 'Construction Law / Building Code - Law No. 646 of 2004 — Historical Context', 'Historical context and overview', 'Construction Law'),
  ('LEB-PROC-001', 'Article 1', 'Objectifs de la loi: application des procédures compétitives comme règle générale, fourniture d''opportunités égales de participation aux marchés publics.', 'fr', 'Public Procurement Law - Law No. 244 dated July 19, 2021, Article Article 1', 'Objectives of the law', 'Public Procurement Law'),
  ('LEB-PROC-001', 'Article 1', 'أهداف القانون: تطبيق الإجراءات التنافسية كقاعدة عامة، توفير فرص متساوية للمشاركة في المناقصات العامة.', 'ar', 'Public Procurement Law - Law No. 244 dated July 19, 2021, Article Article 1', 'Objectives of the law', 'Public Procurement Law'),
  ('LEB-PROC-001', 'Article 15', 'Durabilité et politiques de développement: adoption des marchés publics durables pour orienter le pouvoir d''achat vers des fournitures et services durables.', 'fr', 'Public Procurement Law - Law No. 244 dated July 19, 2021, Article Article 15', 'Sustainable procurement', 'Public Procurement Law'),
  ('LEB-PROC-001', 'Article 15', 'الاستدامة والسياسات التنموية: اعتماد المناقصات العامة المستدامة لتوجيه قوة الشراء نحو الموردات والخدمات المستدامة.', 'ar', 'Public Procurement Law - Law No. 244 dated July 19, 2021, Article Article 15', 'Sustainable procurement', 'Public Procurement Law'),
  ('LEB-PROC-001', 'Article 16', 'Préférences domestiques: les offres de produits nationaux peuvent bénéficier d''une préférence de 10%.', 'fr', 'Public Procurement Law - Law No. 244 dated July 19, 2021, Article Article 16', 'Domestic preference in procurement', 'Public Procurement Law'),
  ('LEB-PROC-001', 'Article 16', 'الأفضلية للمنتجات المحلية: يمكن منح عروض المنتجات الوطنية أفضلية بنسبة 10%.', 'ar', 'Public Procurement Law - Law No. 244 dated July 19, 2021, Article Article 16', 'Domestic preference in procurement', 'Public Procurement Law'),
  ('LEB-PROC-001', 'Article 46', 'Contractation par accord mutuel dans des cas spécifiques.', 'fr', 'Public Procurement Law - Law No. 244 dated July 19, 2021, Article Article 46', 'Negotiated contracts', 'Public Procurement Law'),
  ('LEB-PROC-001', 'Article 46', 'التعاقد بالتراضي في حالات محددة.', 'ar', 'Public Procurement Law - Law No. 244 dated July 19, 2021, Article Article 46', 'Negotiated contracts', 'Public Procurement Law'),
  ('LEB-PROC-001', 'Chapter 4', 'Plateforme électronique centrale pour les marchés publics.', 'fr', 'Public Procurement Law - Law No. 244 dated July 19, 2021, Article Chapter 4', 'E-procurement platform', 'Public Procurement Law'),
  ('LEB-PROC-001', 'Chapter 4', 'المنصة الإلكترونية المركزية للمناقصات العامة.', 'ar', 'Public Procurement Law - Law No. 244 dated July 19, 2021, Article Chapter 4', 'E-procurement platform', 'Public Procurement Law'),
  ('LEB-PROC-001', NULL, 'The Public Procurement Law 244/2021 replaced Lebanon''s outdated procurement system from the 1960s. It was enacted as part of reforms demanded by the International Monetary Fund and international community. The law introduces competitive bidding as the default, establishes a central e-procurement platform, and creates a Complaints Authority for dispute resolution. It entered into force 12 months after publication (July 2022).', 'en', 'Public Procurement Law - Law No. 244 dated July 19, 2021 — Historical Context', 'Historical context and overview', 'Public Procurement Law'),
  ('LEB-ADMIN-001', 'Article 2', 'La juridiction administrative se compose du Conseil d''État et des tribunaux administratifs.', 'fr', 'State Council Organization Law - Decree No. 10434 dated June 14, 1975, Article Article 2', 'Administrative judiciary composition', 'Administrative Law'),
  ('LEB-ADMIN-001', 'Article 2', 'يتألف القضاء الإداري من مجلس الشورى والمحاكم الإدارية.', 'ar', 'State Council Organization Law - Decree No. 10434 dated June 14, 1975, Article Article 2', 'Administrative judiciary composition', 'Administrative Law'),
  ('LEB-ADMIN-001', 'Article 65', 'Le Conseil d''État est compétent pour examiner les actions en annulation contre les décrets d''application et les actes réglementaires des ministres.', 'fr', 'State Council Organization Law - Decree No. 10434 dated June 14, 1975, Article Article 65', 'Jurisdiction over annulment actions', 'Administrative Law'),
  ('LEB-ADMIN-001', 'Article 65', 'يختص مجلس الشورى بالنظر في دعاوى الإلغاء ضد المراسيم التنفيذية والأعمال التنظيمية للوزراء.', 'ar', 'State Council Organization Law - Decree No. 10434 dated June 14, 1975, Article Article 65', 'Jurisdiction over annulment actions', 'Administrative Law'),
  ('LEB-ADMIN-001', 'Chambers', 'Le Conseil d''État se compose de six chambres: une chambre administrative et cinq chambres judiciaires.', 'fr', 'State Council Organization Law - Decree No. 10434 dated June 14, 1975, Article Chambers', 'State Council chambers', 'Administrative Law'),
  ('LEB-ADMIN-001', 'Chambers', 'يتألف مجلس الشورى من ست غرف: غرفة إدارية وخمس غرف قضائية.', 'ar', 'State Council Organization Law - Decree No. 10434 dated June 14, 1975, Article Chambers', 'State Council chambers', 'Administrative Law'),
  ('LEB-ADMIN-001', 'Advisory Function', 'La chambre administrative a le pouvoir de donner des avis et conseils sur les projets de lois et décrets.', 'fr', 'State Council Organization Law - Decree No. 10434 dated June 14, 1975, Article Advisory Function', 'Advisory functions', 'Administrative Law'),
  ('LEB-ADMIN-001', 'Advisory Function', 'للغرفة الإدارية صلاحية إبداء الرأي والمشورة في مشاريع القوانين والمراسيم.', 'ar', 'State Council Organization Law - Decree No. 10434 dated June 14, 1975, Article Advisory Function', 'Advisory functions', 'Administrative Law'),
  ('LEB-ADMIN-001', NULL, 'The State Council was originally established in 1924 during the French Mandate. Decree 10434/1975 reorganized the State Council during the early period of the Lebanese Civil War. The law was amended by Law 227/2000 which provided for the establishment of first-level administrative tribunals in each governorate, though these have not yet been implemented. The State Council serves as both an administrative court and advisory body to the government.', 'en', 'State Council Organization Law - Decree No. 10434 dated June 14, 1975 — Historical Context', 'Historical context and overview', 'Administrative Law'),
  ('LEB-CIVIL-001', 'Article 1', 'Les fonctionnaires publics sont soumis aux dispositions de ce décret-loi.', 'fr', 'Civil Service Law - Decree-Law No. 112 dated June 12, 1959, Article Article 1', 'Scope of application', 'Civil Service Law'),
  ('LEB-CIVIL-001', 'Article 1', 'الموظفون العموميون يخضعون لأحكام هذا المرسوم.', 'ar', 'Civil Service Law - Decree-Law No. 112 dated June 12, 1959, Article Article 1', 'Scope of application', 'Civil Service Law'),
  ('LEB-CIVIL-001', 'Article 15', 'Il est interdit aux fonctionnaires de s''occuper d''affaires politiques ou de participer à des grèves.', 'fr', 'Civil Service Law - Decree-Law No. 112 dated June 12, 1959, Article Article 15', 'Political neutrality and strike prohibition', 'Civil Service Law'),
  ('LEB-CIVIL-001', 'Article 15', 'يحظر على الموظفين التعامل في الشؤون السياسية أو المشاركة في الإضرابات.', 'ar', 'Civil Service Law - Decree-Law No. 112 dated June 12, 1959, Article Article 15', 'Political neutrality and strike prohibition', 'Civil Service Law'),
  ('LEB-CIVIL-001', 'Article 65', 'La participation d''un fonctionnaire à une grève équivaut à une démission.', 'fr', 'Civil Service Law - Decree-Law No. 112 dated June 12, 1959, Article Article 65', 'Strike consequences', 'Civil Service Law'),
  ('LEB-CIVIL-001', 'Article 65', 'مشاركة الموظف في الإضراب تعتبر استقالة.', 'ar', 'Civil Service Law - Decree-Law No. 112 dated June 12, 1959, Article Article 65', 'Strike consequences', 'Civil Service Law'),
  ('LEB-CIVIL-001', 'Article 80', 'Les municipalités qui sont des centres de gouvernorats sont soumises au contrôle du Conseil de la fonction publique.', 'fr', 'Civil Service Law - Decree-Law No. 112 dated June 12, 1959, Article Article 80', 'Municipal civil service oversight', 'Civil Service Law'),
  ('LEB-CIVIL-001', 'Article 80', 'البلديات التي تعتبر مراكز محافظات تخضع لرقابة مجلس الخدمة المدنية.', 'ar', 'Civil Service Law - Decree-Law No. 112 dated June 12, 1959, Article Article 80', 'Municipal civil service oversight', 'Civil Service Law'),
  ('LEB-CIVIL-001', NULL, 'The Civil Service Law was enacted shortly after Lebanon gained independence to establish a professional public administration. It created the framework for civil service recruitment, promotion, discipline, and rights. Decree 114/1959 established the Civil Service Board to oversee civil service matters. The law applies to central government employees and certain municipalities designated as governorate centers.', 'en', 'Civil Service Law - Decree-Law No. 112 dated June 12, 1959 — Historical Context', 'Historical context and overview', 'Civil Service Law'),
  ('LEB-PROP-001', 'Article 1', 'Aucune propriété ne peut être expropriée que pour utilité publique et après paiement d''une indemnité équitable.', 'fr', 'Expropriation Law - Law No. 58 dated May 29, 1991, Article Article 1', 'Constitutional basis for expropriation', 'State Property Law'),
  ('LEB-PROP-001', 'Article 1', 'لا يجوز نزع ملكية أي عقار إلا للمنفعة العامة وقبل دفع تعويض عادل.', 'ar', 'Expropriation Law - Law No. 58 dated May 29, 1991, Article Article 1', 'Constitutional basis for expropriation', 'State Property Law'),
  ('LEB-PROP-001', 'Compensation Process', 'L''indemnisation est déterminée par évaluation d''un comité judiciaire indépendant et est toujours financière.', 'fr', 'Expropriation Law - Law No. 58 dated May 29, 1991, Article Compensation Process', 'Compensation determination', 'State Property Law'),
  ('LEB-PROP-001', 'Compensation Process', 'يحدد التعويض من خلال تقييم لجنة قضائية مستقلة ويكون دائماً مالياً.', 'ar', 'Expropriation Law - Law No. 58 dated May 29, 1991, Article Compensation Process', 'Compensation determination', 'State Property Law'),
  ('LEB-PROP-001', 'Appeal Process', 'Les décisions du comité d''expropriation peuvent faire l''objet d''un appel devant le comité d''appel.', 'fr', 'Expropriation Law - Law No. 58 dated May 29, 1991, Article Appeal Process', 'Appeal mechanism', 'State Property Law'),
  ('LEB-PROP-001', 'Appeal Process', 'يمكن الطعن بقرارات لجنة النزع أمام لجنة الاستئناف.', 'ar', 'Expropriation Law - Law No. 58 dated May 29, 1991, Article Appeal Process', 'Appeal mechanism', 'State Property Law'),
  ('LEB-PROP-001', 'Timeline', 'La durée du projet ne doit pas dépasser 8 ans à compter de la date de publication de l''annonce.', 'fr', 'Expropriation Law - Law No. 58 dated May 29, 1991, Article Timeline', 'Project timeline limit', 'State Property Law'),
  ('LEB-PROP-001', 'Timeline', 'يجب ألا تتجاوز مدة المشروع 8 سنوات من تاريخ نشر الإعلان.', 'ar', 'Expropriation Law - Law No. 58 dated May 29, 1991, Article Timeline', 'Project timeline limit', 'State Property Law'),
  ('LEB-PROP-001', NULL, 'The Expropriation Law was enacted after the Lebanese Civil War to regulate land acquisition for reconstruction and public projects. It implements Article 15 of the Lebanese Constitution which guarantees private property rights while allowing expropriation for public utility with fair compensation. The law establishes the framework for Expropriation Committees and Appellate Expropriation Committees.', 'en', 'Expropriation Law - Law No. 58 dated May 29, 1991 — Historical Context', 'Historical context and overview', 'State Property Law'),
  ('LEB-ENV-002', 'General Provisions', 'La loi vise à prévenir et atténuer la pollution de l''air ambiant provenant de sources fixes et mobiles.', 'fr', 'Air Quality Protection Law - Law No. 78 dated April 19, 2018, Article General Provisions', 'Purpose and scope', 'Environmental Law'),
  ('LEB-ENV-002', 'General Provisions', 'القانون يهدف إلى منع والحد من تلوث الهواء المحيط من المصادر الثابتة والمتنقلة.', 'ar', 'Air Quality Protection Law - Law No. 78 dated April 19, 2018, Article General Provisions', 'Purpose and scope', 'Environmental Law'),
  ('LEB-ENV-002', 'Monitoring', 'Surveillance des polluants atmosphériques via le Programme National de Surveillance de la Qualité de l''Air.', 'fr', 'Air Quality Protection Law - Law No. 78 dated April 19, 2018, Article Monitoring', 'Air quality monitoring', 'Environmental Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LEB-ENV-002', 'Monitoring', 'مراقبة ملوثات الهواء من خلال البرنامج الوطني لمراقبة جودة الهواء.', 'ar', 'Air Quality Protection Law - Law No. 78 dated April 19, 2018, Article Monitoring', 'Air quality monitoring', 'Environmental Law'),
  ('LEB-ENV-002', 'Emission Limits', 'Définition des valeurs limites des polluants dans l''air ambiant incluant CO, NOx, O3, particules, SO2.', 'fr', 'Air Quality Protection Law - Law No. 78 dated April 19, 2018, Article Emission Limits', 'Ambient air quality standards', 'Environmental Law'),
  ('LEB-ENV-002', 'Emission Limits', 'تحديد قيم حدود الملوثات في الهواء المحيط بما فيها CO، NOx، O3، الجسيمات، SO2.', 'ar', 'Air Quality Protection Law - Law No. 78 dated April 19, 2018, Article Emission Limits', 'Ambient air quality standards', 'Environmental Law'),
  ('LEB-ENV-002', 'Climate Change', 'La loi fait référence au changement climatique de manière générale.', 'fr', 'Air Quality Protection Law - Law No. 78 dated April 19, 2018, Article Climate Change', 'Climate change reference', 'Environmental Law'),
  ('LEB-ENV-002', 'Climate Change', 'يشير القانون إلى تغير المناخ بشكل عام.', 'ar', 'Air Quality Protection Law - Law No. 78 dated April 19, 2018, Article Climate Change', 'Climate change reference', 'Environmental Law'),
  ('LEB-ENV-002', NULL, 'Law 78/2018 was enacted to address Lebanon''s significant air pollution problems, particularly in urban areas. The law establishes the National Ambient Air Quality Standards (NAAQS) and creates frameworks for monitoring air pollutants, emission inventories, and early warning systems. It complements Law 444/2002 and aligns with Lebanon''s commitments under the UNFCCC and Paris Agreement.', 'en', 'Air Quality Protection Law - Law No. 78 dated April 19, 2018 — Historical Context', 'Historical context and overview', 'Environmental Law'),
  ('LEB-ENV-003', 'Article 28', 'Permettre aux municipalités de percevoir des frais de traitement des déchets.', 'fr', 'Integrated Solid Waste Management Law - Law No. 80 dated September 24, 2018, Article Article 28', 'Municipal waste treatment fees', 'Environmental Law'),
  ('LEB-ENV-003', 'Article 28', 'السماح للبلديات بتحصيل رسوم معالجة النفايات.', 'ar', 'Integrated Solid Waste Management Law - Law No. 80 dated September 24, 2018, Article Article 28', 'Municipal waste treatment fees', 'Environmental Law'),
  ('LEB-ENV-003', 'Waste Sorting', 'Encourager le tri des déchets à la source et le recyclage.', 'fr', 'Integrated Solid Waste Management Law - Law No. 80 dated September 24, 2018, Article Waste Sorting', 'Source separation and recycling', 'Environmental Law'),
  ('LEB-ENV-003', 'Waste Sorting', 'تشجيع فرز النفايات عند المصدر وإعادة التدوير.', 'ar', 'Integrated Solid Waste Management Law - Law No. 80 dated September 24, 2018, Article Waste Sorting', 'Source separation and recycling', 'Environmental Law'),
  ('LEB-ENV-003', 'Private Sector', 'Permettre la participation du secteur privé dans les opérations de gestion des déchets.', 'fr', 'Integrated Solid Waste Management Law - Law No. 80 dated September 24, 2018, Article Private Sector', 'Private sector involvement', 'Environmental Law'),
  ('LEB-ENV-003', 'Private Sector', 'السماح بمشاركة القطاع الخاص في عمليات إدارة النفايات.', 'ar', 'Integrated Solid Waste Management Law - Law No. 80 dated September 24, 2018, Article Private Sector', 'Private sector involvement', 'Environmental Law'),
  ('LEB-ENV-003', 'Organic Waste', 'Les déchets organiques constituent environ 52% du total des déchets produits au Liban.', 'fr', 'Integrated Solid Waste Management Law - Law No. 80 dated September 24, 2018, Article Organic Waste', 'Organic waste composition', 'Environmental Law'),
  ('LEB-ENV-003', 'Organic Waste', 'النفايات العضوية تشكل حوالي 52% من إجمالي النفايات المنتجة في لبنان.', 'ar', 'Integrated Solid Waste Management Law - Law No. 80 dated September 24, 2018, Article Organic Waste', 'Organic waste composition', 'Environmental Law'),
  ('LEB-ENV-003', NULL, 'Law 80/2018 was enacted in response to Lebanon''s severe waste management crisis that began in 2015. The law provides a framework for integrated solid waste management including provisions for waste sorting, recycling, and treatment. However, critics note it lacks detailed implementation mechanisms and does not adequately address waste prevention, reuse, or extended producer responsibility. The law is currently being amended to address municipal financing issues.', 'en', 'Integrated Solid Waste Management Law - Law No. 80 dated September 24, 2018 — Historical Context', 'Historical context and overview', 'Environmental Law'),
  ('LEB-ENV-004', 'Definition', 'La forêt est un bois comprenant différents arbres enroulés les uns autour des autres.', 'fr', 'Forest Law / Forest Code - Law No. 49 of 1949, Article Definition', 'Forest definition', 'Environmental Law'),
  ('LEB-ENV-004', 'Definition', 'الغابة هي بستان يضم أشجاراً مختلفة ملتفة حول بعضها.', 'ar', 'Forest Law / Forest Code - Law No. 49 of 1949, Article Definition', 'Forest definition', 'Environmental Law'),
  ('LEB-ENV-004', 'Classification', 'Les forêts sont classées en quatre catégories selon la propriété: privée, municipale/villages, État, État avec droits d''usage pour les villages.', 'fr', 'Forest Law / Forest Code - Law No. 49 of 1949, Article Classification', 'Forest classification by ownership', 'Environmental Law'),
  ('LEB-ENV-004', 'Classification', 'تصنف الغابات إلى أربع فئات حسب الملكية: خاصة، بلدية/قرى، دولة، دولة بحقوق الانتفاع للقرى.', 'ar', 'Forest Law / Forest Code - Law No. 49 of 1949, Article Classification', 'Forest classification by ownership', 'Environmental Law'),
  ('LEB-ENV-004', 'Activities', 'La loi réglemente les activités forestières incluant le pâturage, l''élagage, le dépressage, l''éclaircie et la production de charbon.', 'fr', 'Forest Law / Forest Code - Law No. 49 of 1949, Article Activities', 'Regulated forest activities', 'Environmental Law'),
  ('LEB-ENV-004', 'Activities', 'ينظم القانون أنشطة الغابات بما فيها الرعي والتقليم والجذب والتخفيف وإنتاج الفحم.', 'ar', 'Forest Law / Forest Code - Law No. 49 of 1949, Article Activities', 'Regulated forest activities', 'Environmental Law'),
  ('LEB-ENV-004', NULL, 'The Forest Law of 1949 is one of the oldest environmental laws in Lebanon and the region, covering forests that were under the French Mandate. It was amended by Law 85/1991 which imposed severe restrictions on forest activities and banned harvesting from resinous trees (cedar, fir, cypress, oak, juniper). Law 558/1996 further strengthened protection by considering all coniferous forests as protected. Law 195/2000 criminalized illegal operations.', 'en', 'Forest Law / Forest Code - Law No. 49 of 1949 — Historical Context', 'Historical context and overview', 'Environmental Law'),
  ('LEB-ENV-005', 'Article 8', 'La propriété publique de l''eau comprend l''eau dans tous ses états naturels et emplacements géologiques.', 'fr', 'Water Law - Law of 2000, Article Article 8', 'Public ownership of water', 'Environmental Law'),
  ('LEB-ENV-005', 'Article 8', 'الملكية العامة للمياه تشمل المياه بجميع حالاتها الطبيعية والمواقع الجيولوجية.', 'ar', 'Water Law - Law of 2000, Article Article 8', 'Public ownership of water', 'Environmental Law'),
  ('LEB-ENV-005', 'Article 42', 'Détermination des tarifs après prise en compte de l''équilibre financier de l''institution d''eau et de la situation socio-économique des bénéficiaires.', 'fr', 'Water Law - Law of 2000, Article Article 42', 'Water tariff determination', 'Environmental Law'),
  ('LEB-ENV-005', 'Article 42', 'تحديد التعرفات بعد مراعاة التوازن المالي لمؤسسة المياه والوضع الاجتماعي الاقتصادي للمستفيدين.', 'ar', 'Water Law - Law of 2000, Article Article 42', 'Water tariff determination', 'Environmental Law'),
  ('LEB-ENV-005', 'Article 46', 'La liste des tarifs peut inclure: service d''eau potable, service d''assainissement, tarif d''irrigation.', 'fr', 'Water Law - Law of 2000, Article Article 46', 'Types of water tariffs', 'Environmental Law'),
  ('LEB-ENV-005', 'Article 46', 'قائمة التعرفات قد تشمل: خدمة المياه الصالحة للشرب، خدمة الصرف الصحي، تعرفة الري.', 'ar', 'Water Law - Law of 2000, Article Article 46', 'Types of water tariffs', 'Environmental Law'),
  ('LEB-ENV-005', NULL, 'The Water Law of 2000 governs the management and use of Lebanon''s water resources, including surface water and groundwater. It establishes the framework for Water Establishments (WEs) and their financial autonomy, though the Ministry of Energy and Water maintains significant oversight. The law addresses water scarcity issues exacerbated by urbanization, pollution, and climate change.', 'en', 'Water Law - Law of 2000 — Historical Context', 'Historical context and overview', 'Environmental Law'),
  ('LEB-MUN-002', 'Article 9', 'Le Conseil municipal se compose d''un nombre de membres déterminé selon la population: 9 membres jusqu''à 2000 habitants, 12 entre 2001-4000, 15 entre 4001-12000, 18 entre 12001-24000, 21 au-delà de 24000, 24 pour Beyrouth et Tripoli.', 'fr', 'Municipal Law Amendment - Law No. 665 dated December 30, 1997, Article Article 9', 'Municipal Council composition by population', 'Municipal Law'),
  ('LEB-MUN-002', 'Article 9', 'يتركب مجلس البلدية من عدد من الأعضاء يتحدد بحسب عدد السكان: 9 أعضاء حتى 2000 نسمة، 12 عضواً بين 2001-4000، 15 عضواً بين 4001-12000، 18 عضواً بين 12001-24000، 21 عضواً فوق 24000، 24 عضواً لبيروت وطرابلس.', 'ar', 'Municipal Law Amendment - Law No. 665 dated December 30, 1997, Article Article 9', 'Municipal Council composition by population', 'Municipal Law'),
  ('LEB-MUN-002', 'Article 11', 'Les membres du Conseil municipal sont élus au suffrage universel et direct.', 'fr', 'Municipal Law Amendment - Law No. 665 dated December 30, 1997, Article Article 11', 'Election method', 'Municipal Law'),
  ('LEB-MUN-002', 'Article 11', 'ينتخب أعضاء مجلس البلدية بالاقتراع العام والمباشر.', 'ar', 'Municipal Law Amendment - Law No. 665 dated December 30, 1997, Article Article 11', 'Election method', 'Municipal Law'),
  ('LEB-MUN-002', 'Article 21', 'Le Conseil municipal élit un président et un vice-président parmi ses membres par vote secret et à la majorité absolue.', 'fr', 'Municipal Law Amendment - Law No. 665 dated December 30, 1997, Article Article 21', 'Election of President and Vice-President', 'Municipal Law'),
  ('LEB-MUN-002', 'Article 21', 'ينتخب مجلس البلدية رئيساً ونائباً للرئيس من بين أعضائه بالاقتراع السري والأغلبية المطلقة.', 'ar', 'Municipal Law Amendment - Law No. 665 dated December 30, 1997, Article Article 21', 'Election of President and Vice-President', 'Municipal Law'),
  ('LEB-MUN-002', 'Article 23', 'Le Ministre de l''Intérieur peut fixer la date des élections pour qu''elles aient lieu en un seul jour ou en jours séparés.', 'fr', 'Municipal Law Amendment - Law No. 665 dated December 30, 1997, Article Article 23', 'Election scheduling', 'Municipal Law'),
  ('LEB-MUN-002', 'Article 23', 'يحق لوزير الداخلية تحديد موعد الانتخابات لتتم في يوم واحد أو في أيام متفرقة.', 'ar', 'Municipal Law Amendment - Law No. 665 dated December 30, 1997, Article Article 23', 'Election scheduling', 'Municipal Law'),
  ('LEB-MUN-002', 'Article 26', 'L''acclamation n''est autorisée que lorsque des conditions spécifiques sont remplies.', 'fr', 'Municipal Law Amendment - Law No. 665 dated December 30, 1997, Article Article 26', 'Acclamation conditions', 'Municipal Law'),
  ('LEB-MUN-002', 'Article 26', 'التزكية مسموح بها فقط عند استيفاء شروط محددة.', 'ar', 'Municipal Law Amendment - Law No. 665 dated December 30, 1997, Article Article 26', 'Acclamation conditions', 'Municipal Law'),
  ('LEB-MUN-002', NULL, 'Law 665/1997 is a significant amendment to the Municipal Law 118/1977. It updated the composition of municipal councils based on population, modified election procedures, and established clearer rules for municipal governance. The law has been criticized for facilitating the proliferation of municipalities by making their establishment a prerogative of the Minister of Interior rather than a right based on objective criteria.', 'en', 'Municipal Law Amendment - Law No. 665 dated December 30, 1997 — Historical Context', 'Historical context and overview', 'Municipal Law'),
  ('LEB-MUN-003', 'Fund Sources', 'Le Fonds comprend: une surtaxe de 10% sur tous les biens immobiliers bâtis.', 'fr', 'Independent Municipal Fund Law - Law No. 60 of 1988, Article Fund Sources', 'Fund revenue sources', 'Municipal Law'),
  ('LEB-MUN-003', 'Fund Sources', 'يضم الصندوق: ضريبة بنسبة 10% على جميع العقارات المبنية.', 'ar', 'Independent Municipal Fund Law - Law No. 60 of 1988, Article Fund Sources', 'Fund revenue sources', 'Municipal Law'),
  ('LEB-MUN-003', 'Distribution', 'Les fonds sont distribués aux municipalités selon des critères définis.', 'fr', 'Independent Municipal Fund Law - Law No. 60 of 1988, Article Distribution', 'Fund distribution criteria', 'Municipal Law'),
  ('LEB-MUN-003', 'Distribution', 'توزع أموال الصندوق على البلديات وفقاً لمعايير محددة.', 'ar', 'Independent Municipal Fund Law - Law No. 60 of 1988, Article Distribution', 'Fund distribution criteria', 'Municipal Law'),
  ('LEB-MUN-003', 'Exemptions', 'Les exemptions incluent: hôpitaux, établissements d''enseignement, bâtiments utilisés à des fins religieuses.', 'fr', 'Independent Municipal Fund Law - Law No. 60 of 1988, Article Exemptions', 'Property tax exemptions', 'Municipal Law'),
  ('LEB-MUN-003', 'Exemptions', 'الإعفاءات تشمل: المستشفيات، المؤسسات التعليمية، المباني المستخدمة للأغراض الدينية.', 'ar', 'Independent Municipal Fund Law - Law No. 60 of 1988, Article Exemptions', 'Property tax exemptions', 'Municipal Law'),
  ('LEB-MUN-003', NULL, 'Law 60/1988 established the Independent Municipal Fund (IMF) as the main mechanism for financing municipal activities in Lebanon. The fund collects revenues from various sources including a 10% surtax on built properties and distributes them to municipalities. The fund has been criticized for being subject to central government control and political interference in its distribution mechanisms.', 'en', 'Independent Municipal Fund Law - Law No. 60 of 1988 — Historical Context', 'Historical context and overview', 'Municipal Law'),
  ('LEB-ENV-006', 'Noise Standards', 'Définition des limites de bruit autorisées dans les zones résidentielles, commerciales et industrielles.', 'fr', 'Law on the Protection of the Environment from Noise Pollution - Law of 2004, Article Noise Standards', 'Noise pollution standards', 'Environmental Law'),
  ('LEB-ENV-006', 'Noise Standards', 'تحديد حدود الضوضاء المسموح بها في المناطق السكنية والتجارية والصناعية.', 'ar', 'Law on the Protection of the Environment from Noise Pollution - Law of 2004, Article Noise Standards', 'Noise pollution standards', 'Environmental Law'),
  ('LEB-ENV-006', 'Regulated Sources', 'Réglementation du fonctionnement des chantiers de construction, usines et autres sources de bruit.', 'fr', 'Law on the Protection of the Environment from Noise Pollution - Law of 2004, Article Regulated Sources', 'Noise source regulation', 'Environmental Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LEB-ENV-006', 'Regulated Sources', 'تنظيم تشغيل مواقع البناء والمصانع ومصادر الضوضاء الأخرى.', 'ar', 'Law on the Protection of the Environment from Noise Pollution - Law of 2004, Article Regulated Sources', 'Noise source regulation', 'Environmental Law'),
  ('LEB-ENV-006', 'Public Awareness', 'Encouragement des campagnes de sensibilisation du public sur les impacts sanitaires de la pollution sonore.', 'fr', 'Law on the Protection of the Environment from Noise Pollution - Law of 2004, Article Public Awareness', 'Public awareness campaigns', 'Environmental Law'),
  ('LEB-ENV-006', 'Public Awareness', 'تشجيع حملات التوعية العامة حول آثار التلوث الضوضائي على الصحة.', 'ar', 'Law on the Protection of the Environment from Noise Pollution - Law of 2004, Article Public Awareness', 'Public awareness campaigns', 'Environmental Law'),
  ('LEB-ENV-006', NULL, 'The Noise Pollution Law was enacted in 2004 to address growing concerns about noise pollution in Lebanon''s urban areas. The law sets permissible noise levels for different zones and regulates noise-generating activities. However, enforcement has been limited due to weak monitoring capacity and lack of resources.', 'en', 'Law on the Protection of the Environment from Noise Pollution - Law of 2004 — Historical Context', 'Historical context and overview', 'Environmental Law'),
  ('LEB-ENV-007', 'Article 9', 'Pénalise toute personne déversant dans les eaux de mer des produits chimiques ou déchets dangereux.', 'fr', 'Preservation of the Environment against Pollution from Dangerous Waste and Hazardous Substances - Law No. 64 of 1988, Article Article 9', 'Marine pollution prohibition', 'Environmental Law'),
  ('LEB-ENV-007', 'Article 9', 'يجريم أي شخص ي discharge في مياه البحر أي مواد كيميائية أو نفايات ضارة.', 'ar', 'Preservation of the Environment against Pollution from Dangerous Waste and Hazardous Substances - Law No. 64 of 1988, Article Article 9', 'Marine pollution prohibition', 'Environmental Law'),
  ('LEB-ENV-007', 'Hazardous Waste', 'Réglementation de la collecte, transport et traitement des déchets dangereux.', 'fr', 'Preservation of the Environment against Pollution from Dangerous Waste and Hazardous Substances - Law No. 64 of 1988, Article Hazardous Waste', 'Hazardous waste management', 'Environmental Law'),
  ('LEB-ENV-007', 'Hazardous Waste', 'تنظيم جمع ونقل ومعالجة النفايات الخطرة.', 'ar', 'Preservation of the Environment against Pollution from Dangerous Waste and Hazardous Substances - Law No. 64 of 1988, Article Hazardous Waste', 'Hazardous waste management', 'Environmental Law'),
  ('LEB-ENV-007', NULL, 'Law 64/1988 was one of Lebanon''s earliest environmental protection laws, addressing pollution from dangerous waste and hazardous substances. It was enacted before the comprehensive Environmental Protection Law 444/2002 and remains in force for specific hazardous waste matters.', 'en', 'Preservation of the Environment against Pollution from Dangerous Waste and Hazardous Substances - Law No. 64 of 1988 — Historical Context', 'Historical context and overview', 'Environmental Law'),
  ('LB-CIV-001-EXPANDED', '1', 'Definition of Obligation: An obligation is a legal bond by which one or more persons are bound towards one or more other persons to give, to do, or not to do something.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 1', 'Definition of Obligation', 'civil'),
  ('LB-CIV-001-EXPANDED', '2', 'Sources of Obligations: Obligations arise from contracts, quasi-contracts, torts (unlawful acts), quasi-torts, and the law.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 2', 'Sources of Obligations', 'civil'),
  ('LB-CIV-001-EXPANDED', '3', 'Good Faith in Obligations: All obligations must be performed in good faith. The parties must act honestly and fairly in the performance of their obligations and in the exercise of their rights.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 3', 'Good Faith in Obligations', 'civil'),
  ('LB-CIV-001-EXPANDED', '165', 'Definition of Contract: A contract is an agreement by which one or more persons bind themselves towards one or more other persons to give, to do, or not to do something. A contract is formed by the meeting of an offer and an acceptance.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 165', 'Definition of Contract', 'civil'),
  ('LB-CIV-001-EXPANDED', '166', 'Essential Elements of Contract: For a contract to be validly formed, the following conditions must be met: (1) consent of the parties; (2) capacity to contract; (3) a definite object forming the subject matter of the contract; (4) a lawful cause.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 166', 'Essential Elements of Contract', 'civil'),
  ('LB-CIV-001-EXPANDED', '167', 'Freedom of Contract: The parties are free to determine the content of the contract, provided they do not violate public order or morality. Contractual freedom includes the freedom to enter into a contract, to choose the other contracting party, and to determine the terms of the contract.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 167', 'Freedom of Contract', 'civil'),
  ('LB-CIV-001-EXPANDED', '168', 'Binding Force of Contract: A lawfully formed contract is binding upon the parties. It can be revoked or modified only by the mutual consent of the parties or on grounds provided by law. Contracts must be performed in good faith.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 168', 'Binding Force of Contract', 'civil'),
  ('LB-CIV-001-EXPANDED', '169', 'Consent: Consent is the agreement of the wills of the contracting parties on the essential elements of the contract. Consent must be free and informed.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 169', 'Consent', 'civil'),
  ('LB-CIV-001-EXPANDED', '170', 'Offer: An offer is a unilateral declaration of will addressed to one or more persons, containing all the essential elements of the contract and expressing the intention to be bound upon acceptance.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 170', 'Offer', 'civil'),
  ('LB-CIV-001-EXPANDED', '171', 'Acceptance: Acceptance is the expression of the offeree''s agreement to the terms of the offer. Acceptance must correspond to the offer. An acceptance that modifies the terms of the offer constitutes a counter-offer.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 171', 'Acceptance', 'civil'),
  ('LB-CIV-001-EXPANDED', '172', 'Silence as Acceptance: Silence does not constitute acceptance unless the circumstances or the relationship between the parties indicate otherwise, or unless such silence is considered acceptance under commercial custom.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 172', 'Silence as Acceptance', 'civil'),
  ('LB-CIV-001-EXPANDED', '202', 'Error (Mistake): A contract may be annulled if one of the parties was in error regarding the substance of the thing that is the object of the contract, or regarding a quality that was essential in the eyes of the parties. Error regarding the person of the other contracting party is a ground for annulment only in contracts where the personality of the contracting party is essential.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 202', 'Error (Mistake)', 'civil'),
  ('LB-CIV-001-EXPANDED', '207', 'Fraud (Dol): Fraud is a ground for annulment of the contract when the artifices employed by one of the parties are such that without them the other party would not have contracted. Fraud is not presumed and must be proven.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 207', 'Fraud (Dol)', 'civil'),
  ('LB-CIV-001-EXPANDED', '209', 'Duress (Violence): Violence is a ground for annulment of the contract when it has been exercised on the contracting party in such a manner as to produce in the mind of a reasonable person a fear of exposing himself or his property to serious and imminent harm. Violence may be physical or moral.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 209', 'Duress (Violence)', 'civil'),
  ('LB-CIV-001-EXPANDED', '213', 'Lesion (Lésion): Lesion does not, in general, vitiate a contract. However, when a party exploits the other party''s weakness, distress, or inexperience to obtain an excessive advantage, the contract may be rescinded or the obligation reduced to a reasonable limit.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 213', 'Lesion (Lésion)', 'civil'),
  ('LB-CIV-001-EXPANDED', '215', 'Capacity to Contract: Every person has the capacity to contract unless declared incapable by law. Minors, interdicted persons, and persons of unsound mind lack full capacity to contract.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 215', 'Capacity to Contract', 'civil'),
  ('LB-CIV-001-EXPANDED', '216', 'Minors: A minor who has not reached the age of majority cannot enter into a valid contract. However, contracts entered into by a minor may be ratified upon reaching the age of majority. Contracts for necessities may bind a minor to the extent of the benefit received.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 216', 'Minors', 'civil'),
  ('LB-CIV-001-EXPANDED', '221', 'Object of the Contract: The object of the obligation must be a thing or an act that is determinate or determinable, possible, and lawful. Things that are outside commerce cannot be the object of a contract.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 221', 'Object of the Contract', 'civil'),
  ('LB-CIV-001-EXPANDED', '225', 'Cause of the Obligation: The cause is the reason why each party undertakes an obligation. The cause must exist, be lawful, and not be contrary to public order or morality. A contract without a cause or with an unlawful cause is void.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 225', 'Cause of the Obligation', 'civil'),
  ('LB-CIV-001-EXPANDED', '228', 'Performance of Obligations: The debtor is bound to perform his obligation exactly as stipulated. If performance in kind is not possible, the debtor may be ordered to pay damages.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 228', 'Performance of Obligations', 'civil'),
  ('LB-CIV-001-EXPANDED', '229', 'Specific Performance: The creditor may demand specific performance of the obligation. If the debtor fails to perform, the court may authorize the creditor to have the performance carried out at the debtor''s expense.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 229', 'Specific Performance', 'civil'),
  ('LB-CIV-001-EXPANDED', '230', 'Penalty Clause: The parties may agree in advance on the amount of damages to be paid in case of non-performance or delay in performance. The court may reduce or increase the penalty if it is manifestly excessive or derisory.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 230', 'Penalty Clause', 'civil'),
  ('LB-CIV-001-EXPANDED', '252', 'Contractual Damages - Conditions: The debtor is liable for damages when he fails to perform his obligation in whole or in part, or when he is late in performing it, unless he proves that the failure or delay is due to a cause beyond his control.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 252', 'Contractual Damages - Conditions', 'civil'),
  ('LB-CIV-001-EXPANDED', '253', 'Extent of Damages: Damages shall include the loss actually suffered (damnum emergens) and the profit of which the creditor has been deprived (lucrum cessans). Damages are limited to what was foreseen or what could have been foreseen at the time of contracting.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 253', 'Extent of Damages', 'civil'),
  ('LB-CIV-001-EXPANDED', '254', 'Moral Damages: Moral damages may be awarded in addition to material damages when the non-performance has caused moral suffering. Moral damages include pain and suffering, harm to reputation, and emotional distress.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 254', 'Moral Damages', 'civil'),
  ('LB-CIV-001-EXPANDED', '122', 'General Principle of Tort Liability: Any act whatsoever of a person that causes damage to another obliges the person by whose fault the damage occurred to compensate the injured party. This is the general principle of civil liability based on fault.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 122', 'General Principle of Tort Liability', 'civil'),
  ('LB-CIV-001-EXPANDED', '123', 'Definition of Fault: A fault is any act or omission that a prudent and diligent person would not have committed in similar circumstances. Fault includes intentional acts (dol) and negligence (imprudence, carelessness, lack of attention).', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 123', 'Definition of Fault', 'civil'),
  ('LB-CIV-001-EXPANDED', '124', 'Causation: The plaintiff must prove the existence of a causal link between the defendant''s fault and the damage suffered. The damage must be the direct and immediate consequence of the fault.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 124', 'Causation', 'civil'),
  ('LB-CIV-001-EXPANDED', '125', 'Damage: Compensable damage includes material damage (loss of property, lost profits) and moral damage (pain, suffering, harm to reputation). The damage must be certain, personal, and direct.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 125', 'Damage', 'civil'),
  ('LB-CIV-001-EXPANDED', '131', 'Liability for Acts of Others: A person is liable not only for the damage caused by his own act but also for damage caused by the acts of persons for whom he is responsible: parents for their minor children, masters and employers for their servants and employees, teachers and artisans for their pupils and apprentices.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 131', 'Liability for Acts of Others', 'civil'),
  ('LB-CIV-001-EXPANDED', '132', 'Employer Liability (Vicarious): Masters and employers are responsible for damage caused by their servants and employees in the exercise of their functions. This responsibility exists even if the employer has committed no personal fault.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 132', 'Employer Liability (Vicarious)', 'civil'),
  ('LB-CIV-001-EXPANDED', '133', 'Liability for Things: A person who has custody of a thing is responsible for the damage caused by that thing, unless he proves force majeure or the fault of the victim. The custodian of a thing is the person who has the use, control, and direction of the thing.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 133', 'Liability for Things', 'civil'),
  ('LB-CIV-001-EXPANDED', '134', 'Liability for Animals: The owner of an animal or the person who uses it is responsible for the damage caused by the animal, whether the animal was in the owner''s custody or had strayed or escaped.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 134', 'Liability for Animals', 'civil'),
  ('LB-CIV-001-EXPANDED', '135', 'Liability for Buildings: The owner of a building is responsible for the damage caused by the collapse of the building when such collapse is due to lack of maintenance or a defect in construction.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 135', 'Liability for Buildings', 'civil'),
  ('LB-CIV-001-EXPANDED', '140', 'Management of Another''s Affairs (Gestion d''affaires): A person who voluntarily manages the affairs of another without being authorized to do so is bound to continue the management until the principal is able to attend to the matter himself. The manager must manage the affairs as a prudent administrator.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 140', 'Management of Another''s Affairs (Gestion d''affaires)', 'civil'),
  ('LB-CIV-001-EXPANDED', '141', 'Undue Payment (Paiement de l''indu): A person who has paid what was not due has the right to recover the payment. The recipient must return what was paid, whether the payment was made by mistake of fact or mistake of law.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 141', 'Undue Payment (Paiement de l''indu)', 'civil'),
  ('LB-CIV-001-EXPANDED', '142', 'Unjust Enrichment: A person who is enriched without cause at the expense of another must indemnify the other to the extent of the enrichment. The action for unjust enrichment is subsidiary and may be exercised only when no other legal action is available.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 142', 'Unjust Enrichment', 'civil'),
  ('LB-CIV-001-EXPANDED', '290', 'Payment (Performance): An obligation is extinguished by payment, that is, by the voluntary performance of the obligation. Payment must be made to the creditor or to his authorized agent.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 290', 'Payment (Performance)', 'civil'),
  ('LB-CIV-001-EXPANDED', '299', 'Set-Off (Compensation): Set-off takes place by operation of law when two persons are reciprocally debtor and creditor of each other. Set-off extinguishes both debts to the extent of the smaller debt.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 299', 'Set-Off (Compensation)', 'civil'),
  ('LB-CIV-001-EXPANDED', '305', 'Release of Debt (Remise de dette): The creditor may release the debtor from his obligation. The release may be total or partial. A release is not presumed and must be proven.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 305', 'Release of Debt (Remise de dette)', 'civil'),
  ('LB-CIV-001-EXPANDED', '307', 'Novation: Novation is the substitution of a new obligation for an old one. Novation may take place by changing the object of the obligation, the cause, or the person of the debtor.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 307', 'Novation', 'civil');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-CIV-001-EXPANDED', '310', 'Prescription (Statute of Limitations): Obligations are extinguished by prescription when the creditor fails to exercise his right within the time period fixed by law. The general prescription period is ten years. Special shorter periods apply to certain obligations as provided by law.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 310', 'Prescription (Statute of Limitations)', 'civil'),
  ('LB-CIV-001-EXPANDED', '373', 'Definition of Sale: A sale is a contract by which one party (the seller) transfers or undertakes to transfer ownership of a thing to another party (the buyer) in exchange for a price in money.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 373', 'Definition of Sale', 'civil'),
  ('LB-CIV-001-EXPANDED', '374', 'Essential Elements of Sale: The essential elements of a sale are: (1) the thing sold; (2) the price; and (3) the consent of the parties. The sale is complete when the parties have agreed on the thing and the price.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 374', 'Essential Elements of Sale', 'civil'),
  ('LB-CIV-001-EXPANDED', '375', 'Obligations of the Seller: The seller is bound to: (1) deliver the thing sold; (2) guarantee the buyer''s peaceful possession of the thing; and (3) guarantee against hidden defects.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 375', 'Obligations of the Seller', 'civil'),
  ('LB-CIV-001-EXPANDED', '376', 'Warranty Against Hidden Defects: The seller warrants the buyer against hidden defects that render the thing unfit for the use for which it was intended, or that diminish its value to such an extent that the buyer would not have purchased it or would have paid a lesser price. The warranty does not extend to apparent defects that the buyer could have discovered by reasonable inspection.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 376', 'Warranty Against Hidden Defects', 'civil'),
  ('LB-CIV-001-EXPANDED', '377', 'Obligations of the Buyer: The buyer is bound to: (1) pay the price at the time and place agreed upon; (2) take delivery of the thing sold. If the buyer fails to pay the price, the seller may demand performance or dissolution of the sale with damages.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 377', 'Obligations of the Buyer', 'civil'),
  ('LB-CIV-001-EXPANDED', '543', 'Definition of Lease: A lease (bail) is a contract by which one party (the lessor) binds himself to grant the other party (the lessee) the enjoyment of a thing during a specified period in exchange for a rent (loyer) that the lessee undertakes to pay.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 543', 'Definition of Lease', 'civil'),
  ('LB-CIV-001-EXPANDED', '544', 'Obligations of the Lessor: The lessor is bound to: (1) deliver the thing in good condition; (2) maintain the thing in a condition suitable for the use intended; (3) guarantee the lessee''s peaceful enjoyment.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 544', 'Obligations of the Lessor', 'civil'),
  ('LB-CIV-001-EXPANDED', '545', 'Obligations of the Lessee: The lessee is bound to: (1) use the thing as a prudent administrator and in accordance with its intended use; (2) pay the rent at the agreed times; (3) return the thing at the end of the lease in the condition in which it was received, subject to normal wear and tear.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 545', 'Obligations of the Lessee', 'civil'),
  ('LB-CIV-001-EXPANDED', '546', 'Termination of Lease: A lease for a fixed term expires at the end of the agreed period without the need for notice. A lease for an indefinite period may be terminated by either party by giving notice as provided by law or custom.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 546', 'Termination of Lease', 'civil'),
  ('LB-CIV-001-EXPANDED', '769', 'Definition of Mandate: A mandate (procuration) is a contract by which one person (the mandator or principal) gives another person (the mandatary or agent) the power to act on his behalf. A mandate may be general or special.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 769', 'Definition of Mandate', 'civil'),
  ('LB-CIV-001-EXPANDED', '770', 'Obligations of the Agent: The agent is bound to: (1) execute the mandate diligently; (2) account to the principal for the performance of the mandate; (3) return to the principal everything received in the execution of the mandate.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 770', 'Obligations of the Agent', 'civil'),
  ('LB-CIV-001-EXPANDED', '771', 'Obligations of the Principal: The principal is bound to: (1) reimburse the agent for expenses incurred; (2) indemnify the agent for losses suffered in the execution of the mandate; (3) pay the agent''s remuneration if agreed upon.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 771', 'Obligations of the Principal', 'civil'),
  ('LB-CIV-001-EXPANDED', '624', 'Definition of Employment Contract: A contract of employment is a contract by which one person (the employee) undertakes to place his services at the disposal of another person (the employer) under the latter''s direction and supervision, in exchange for remuneration.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 624', 'Definition of Employment Contract', 'civil'),
  ('LB-CIV-001-EXPANDED', '625', 'Duration: A contract of employment may be for a fixed or indefinite period. A contract for a fixed period expires at the end of the agreed term. A contract for an indefinite period may be terminated by either party by giving reasonable notice.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 625', 'Duration', 'civil'),
  ('LB-CIV-001-EXPANDED', '626', 'Employer Obligations Under Civil Code: The employer is bound to: (1) pay the agreed remuneration; (2) provide the necessary means for the employee to perform the work; (3) ensure the health and safety of the employee; (4) deliver a certificate of employment upon termination.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 626', 'Employer Obligations Under Civil Code', 'civil'),
  ('LB-CIV-001-EXPANDED', '627', 'Employee Obligations Under Civil Code: The employee is bound to: (1) perform the work personally and diligently; (2) follow the lawful instructions of the employer; (3) not engage in conduct harmful to the employer''s interests.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 627', 'Employee Obligations Under Civil Code', 'civil'),
  ('LB-CIV-001-EXPANDED', '652', 'Termination Notice Requirements: Where termination of the contract issues from the employer and the contract has been in force for an indefinite period, the employer must give prior notice. The notice period depends on the duration of service and the nature of employment. Failure to give proper notice entitles the employee to compensation equivalent to the wages for the notice period.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 652', 'Termination Notice Requirements', 'civil'),
  ('LB-CIV-001-EXPANDED', '656', 'Compensation on Termination: Where the employer terminates the contract without just cause, the employee is entitled to compensation. The compensation shall take into account the employee''s length of service, the nature of the employment, and any other relevant circumstances.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 656', 'Compensation on Termination', 'civil'),
  ('LB-CIV-001-EXPANDED', '750', 'Loan for Use (Commodat): A loan for use (prêt à usage) is a contract by which one party delivers a thing to another for the latter''s use, with the obligation to return the same thing. The borrower must use the thing for the purpose agreed upon and must care for it as a prudent administrator.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 750', 'Loan for Use (Commodat)', 'civil'),
  ('LB-CIV-001-EXPANDED', '755', 'Loan for Consumption (Mutuum): A loan for consumption (prêt de consommation) is a contract by which one party delivers fungible things to another, who undertakes to return things of the same kind, quality, and quantity. Money loans are the most common form of loans for consumption.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 755', 'Loan for Consumption (Mutuum)', 'civil'),
  ('LB-CIV-001-EXPANDED', '756', 'Interest on Loans: Interest may be stipulated in the loan contract. The rate of interest must not exceed the legal maximum. Compound interest (interest on interest) is prohibited unless agreed upon in writing and for periods of not less than one year.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 756', 'Interest on Loans', 'civil'),
  ('LB-CIV-001-EXPANDED', '745', 'Definition of Suretyship: Suretyship (cautionnement) is a contract by which a person (the surety) undertakes towards the creditor to perform the obligation of the principal debtor if the latter fails to perform it. Suretyship may be simple or solidary.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 745', 'Definition of Suretyship', 'civil'),
  ('LB-CIV-001-EXPANDED', '746', 'Rights of the Surety: The surety who has paid the debt is subrogated to the rights of the creditor against the principal debtor. The surety has a right of recourse against the principal debtor for the amount paid.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 746', 'Rights of the Surety', 'civil'),
  ('LB-CIV-001-EXPANDED', '689', 'Definition of Deposit: A deposit (dépôt) is a contract by which a person (the depositor) delivers a movable thing to another person (the depositary) who undertakes to keep it and return it in kind. The depositary must keep the thing with the same care as he keeps his own things.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 689', 'Definition of Deposit', 'civil'),
  ('LB-CIV-001-EXPANDED', '822', 'Definition of Partnership: A partnership (société) is a contract by which two or more persons agree to put something in common with a view to sharing the profits that may result therefrom. Each partner contributes money, property, industry, or skill.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 822', 'Definition of Partnership', 'civil'),
  ('LB-CIV-001-EXPANDED', '823', 'Partners'' Obligations: Each partner must contribute what was agreed upon and share in the losses as well as in the profits. A clause exempting a partner from sharing in losses is void (clause léonine).', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 823', 'Partners'' Obligations', 'civil'),
  ('LB-CIV-001-EXPANDED', '95', 'Definition of Mortgage: A mortgage (hypothèque) is a real right over immovable property assigned for the performance of an obligation. The mortgage gives the creditor the right to be paid from the proceeds of the sale of the property in preference to other creditors.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 95', 'Definition of Mortgage', 'civil'),
  ('LB-CIV-001-EXPANDED', '96', 'Pledge (Gage): A pledge is a contract by which a debtor or a third person delivers a movable thing to the creditor as security for the debt. The pledgee has the right to retain the pledged thing until the debt is paid and, in case of non-payment, to have the thing sold and be paid from the proceeds.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 96', 'Pledge (Gage)', 'civil'),
  ('LB-CIV-001-EXPANDED', '260', 'Force Majeure: The debtor is released from liability when the non-performance of his obligation is due to force majeure or an act of God (cas fortuit), that is, an event that is irresistible, unforeseeable, and external to the debtor. Events such as war, natural disasters, and government prohibitions may constitute force majeure.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 260', 'Force Majeure', 'civil'),
  ('LB-CIV-001-EXPANDED', '261', 'Imprévision (Hardship): When, as a result of exceptional and unforeseeable events of a general nature, the performance of the obligation becomes excessively onerous and threatens the debtor with exorbitant loss, the court may, according to the circumstances, reduce the obligation to a reasonable limit or dissolve the contract.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 261', 'Imprévision (Hardship)', 'civil'),
  ('LB-CIV-001-EXPANDED', '262', 'Assignment of Claims: A creditor may assign his claim to a third party without the consent of the debtor. The assignment must be in writing and is effective against the debtor only upon notification.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 262', 'Assignment of Claims', 'civil'),
  ('LB-CIV-001-EXPANDED', '263', 'Subrogation: Subrogation operates by law or by agreement. The person who pays the debt of another is subrogated to the rights of the creditor. Legal subrogation occurs automatically in favor of the person who pays a debt for which he is liable jointly with others.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 263', 'Subrogation', 'civil'),
  ('LB-CIV-001-EXPANDED', '677', 'Right of Retention: A creditor who holds a thing belonging to his debtor may retain that thing until the debt is paid, provided there is a connection between the claim and the thing retained.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 677', 'Right of Retention', 'civil'),
  ('LB-CIV-001-EXPANDED', '941', 'Partition: Every co-owner has the right to demand partition of the common property. Partition may be effected by agreement or by judicial decision. Partition has retroactive effect, and each co-owner is deemed to have owned his share from the beginning.', 'en', 'Code of Obligations and Contracts (1932) - Expanded, Article 941', 'Partition', 'civil'),
  ('LB-CIV-001-EXPANDED', NULL, 'The Lebanese Code of Obligations and Contracts was promulgated on 9 March 1932 during the French Mandate period. It is heavily influenced by the French Civil Code and the Ottoman Mejelle. The Code contains 1,106 articles organized into several books covering general obligations, specific contracts, and civil liability. It remains the foundational civil law text in Lebanon governing contractual relationships, torts, property, and civil obligations.', 'en', 'Code of Obligations and Contracts (1932) - Expanded — Historical Context', 'Historical context and overview', 'civil'),
  ('LB-CRIM-001', '1-12', 'General principles: legality of offenses and punishments, territorial application, temporal application of criminal law.', 'en', 'Penal Code, Article 1-12', 'General principles', 'Criminal Law'),
  ('LB-CRIM-001', '185-232', 'Offenses against state security, treason, espionage.', 'en', 'Penal Code, Article 185-232', 'State security offenses', 'Criminal Law'),
  ('LB-CRIM-001', '340-341', 'Offenses related to unlawful assembly and strikes.', 'en', 'Penal Code, Article 340-341', 'Public order offenses', 'Criminal Law'),
  ('LB-CRIM-001', '385-420', 'Offenses against public morals, sexual offenses.', 'en', 'Penal Code, Article 385-420', 'Morality offenses', 'Criminal Law'),
  ('LB-CRIM-001', '547-558', 'Homicide and related offenses: intentional killing, manslaughter, assault causing death.', 'en', 'Penal Code, Article 547-558', 'Homicide', 'Criminal Law'),
  ('LB-CRIM-001', '569-578', 'Assault and battery, bodily harm offenses.', 'en', 'Penal Code, Article 569-578', 'Assault', 'Criminal Law'),
  ('LB-CRIM-001', '635-667', 'Theft, robbery, and related property offenses.', 'en', 'Penal Code, Article 635-667', 'Theft', 'Criminal Law'),
  ('LB-CRIM-001', '668-682', 'Fraud, breach of trust, embezzlement.', 'en', 'Penal Code, Article 668-682', 'Fraud and financial crimes', 'Criminal Law'),
  ('LB-CRIM-001', NULL, 'Enacted during the French Mandate, the Lebanese Penal Code was modeled on the French Penal Code and the Syrian Penal Code (itself French-derived). It has undergone significant reforms in recent decades, particularly regarding women''s rights (repeal of honor crime provisions), domestic violence criminalization, torture prohibition, and sexual harassment. Lebanon retains the death penalty in the code but has maintained a de facto moratorium on executions since 2004. Key ongoing reform debates include: decriminalization of drug use (Article 127-related), defamation reform, and LGBTQ+ rights (Article 534 criminalizing ''unnatural'' sexual relations remains controversial).', 'en', 'Penal Code — Historical Context', 'Historical context and overview', 'Criminal Law'),
  ('LB-CRIM-001', 'various', 'Post-war amendments to criminal penalties and procedures.', 'en', 'Penal Code — Amendment: Law No. 239/1993', 'Amendment', 'Criminal Law'),
  ('LB-CRIM-001', NULL, 'Law on Protection of Women and Family Members from Domestic Violence. Added protections and created new offenses related to domestic violence.', 'en', 'Penal Code — Amendment: Law No. 293/2014 (Domestic Violence)', 'Amendment', 'Criminal Law'),
  ('LB-CRIM-001', '385, 507, 519, 532', 'Criminalized sexual harassment. Amended and strengthened provisions related to sexual offenses.', 'en', 'Penal Code — Amendment: Law No. 205/2020 (Sexual Harassment)', 'Amendment', 'Criminal Law'),
  ('LB-CRIM-001', '562', 'Reduced but did not fully eliminate mitigating circumstances for so-called ''honor crimes''. Article 562 was later fully repealed.', 'en', 'Penal Code — Amendment: Law No. 550/1996 (Repeal of Article 562 - Honor Crimes)', 'Amendment', 'Criminal Law'),
  ('LB-CRIM-001', '562', 'Abolished Article 562 which had provided reduced sentences for ''honor crimes''. Landmark reform after years of civil society advocacy.', 'en', 'Penal Code — Amendment: Law No. 164/2011 (Abolition of reduced sentences for honor crimes)', 'Amendment', 'Criminal Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-CRIM-001', '401', 'Criminalized torture in line with Lebanon''s obligations under the Convention Against Torture. Defined torture as a crime and established penalties.', 'en', 'Penal Code — Amendment: Law No. 65/2017 (Torture)', 'Amendment', 'Criminal Law'),
  ('LB-CRIM-001', NULL, 'Amended and strengthened Lebanon''s anti-trafficking framework.', 'en', 'Penal Code — Amendment: Law No. 75/2024 (Human Trafficking)', 'Amendment', 'Criminal Law'),
  ('LB-CRIM-002', NULL, 'Replaced the previous Code of Criminal Procedure (dating from 1948/French Mandate era). Modernized criminal procedure including pre-trial detention rules, rights of the accused, investigation procedures, trial procedures, and appeals. Introduced greater protections for suspects and defendants, including limits on pre-trial detention and right to counsel. However, implementation has been criticized by human rights organizations for gaps in practice.', 'en', 'Code of Criminal Procedure — Historical Context', 'Historical context and overview', 'Criminal Law'),
  ('LB-CRIM-003', NULL, 'Landmark legislation criminalizing domestic violence in Lebanon. Result of years of civil society advocacy, particularly by KAFA (Enough) Violence & Exploitation. Introduced protection orders, established specialized procedures for domestic violence cases, and created the offense of family violence. Criticized by some women''s rights organizations for not going far enough, particularly regarding marital rape provisions which were weakened during parliamentary debate.', 'en', 'Law on Protection of Women and Family Members from Domestic Violence — Historical Context', 'Historical context and overview', 'Criminal Law'),
  ('LB-CRIM-004', NULL, 'Comprehensive narcotics legislation replacing earlier laws. Covers production, trafficking, possession, and use of narcotic drugs and psychotropic substances. Provides for treatment alternatives for drug users (Article 127). Ongoing debate about reforming drug policy in Lebanon, with civil society organizations advocating for decriminalization of personal use.', 'en', 'Narcotics, Drugs and Psychotropic Substances Law — Historical Context', 'Historical context and overview', 'Criminal Law'),
  ('LB-CRIM-005', NULL, 'Landmark human rights legislation criminalizing torture. Enacted to bring Lebanon into compliance with the Convention Against Torture (ratified 2000). Defines torture as a crime, establishes penalties including imprisonment, and provides for victims'' compensation. Also established the National Preventive Mechanism against Torture.', 'en', 'Law Criminalizing Torture and Other Cruel, Inhuman or Degrading Treatment or Punishment — Historical Context', 'Historical context and overview', 'Criminal Law'),
  ('LBN-CRIM-001', '1', 'Nullum crimen, nulla poena sine lege - Aucune peine ne peut être prononcée pour un crime qui n''était pas prévu par la loi au moment de sa commission', 'fr', 'Penal Code, Article 1', 'Principle of legality', 'Criminal Law'),
  ('LBN-CRIM-001', '1', 'لا تفرض عقوبة ولا تدبير احترازي أو إصلاحي من أجل جرم لم يكن القانون قد نص عليه حين اقترافه', 'ar', 'Penal Code, Article 1', 'Principle of legality', 'Criminal Law'),
  ('LBN-CRIM-001', '6', 'Aucune peine ne peut être prononcée qui n''était pas prévue par la loi au moment de la commission du crime', 'fr', 'Penal Code, Article 6', 'Legality of penalties', 'Criminal Law'),
  ('LBN-CRIM-001', '6', 'لا يقضي بأي عقوبة لم ينص القانون عليها حين اقتراف الجرم', 'ar', 'Penal Code, Article 6', 'Legality of penalties', 'Criminal Law'),
  ('LBN-CRIM-001', '15-21', 'Application de la loi pénale selon le lieu - Compétence territoriale et personnelle', 'fr', 'Penal Code, Article 15-21', 'Territorial and personal jurisdiction', 'Criminal Law'),
  ('LBN-CRIM-001', '15-21', 'تطبيق الشريعة الجزائية من حيث المكان - الصلاحية الإقليمية والشخصية', 'ar', 'Penal Code, Article 15-21', 'Territorial and personal jurisdiction', 'Criminal Law'),
  ('LBN-CRIM-001', '49-67', 'Peines principales - Mort, travaux forcés à perpétuité et à temps, réclusion, emprisonnement, détention correctionnelle, amende', 'fr', 'Penal Code, Article 49-67', 'Principal penalties', 'Criminal Law'),
  ('LBN-CRIM-001', '49-67', 'العقوبات الأصلية - الإعدام، الأشغال الشاقة المؤيدة والمؤقتة، الاعتقال، الحبس، التوقيف التكديري، الغرامة', 'ar', 'Penal Code, Article 49-67', 'Principal penalties', 'Criminal Law'),
  ('LBN-CRIM-001', '68-117', 'Peines complémentaires et mesures préventives et réparatrices', 'fr', 'Penal Code, Article 68-117', 'Additional penalties and preventive measures', 'Criminal Law'),
  ('LBN-CRIM-001', '68-117', 'العقوبات الإضافية والتدابير الاحترازية والإصلاحية', 'ar', 'Penal Code, Article 68-117', 'Additional penalties and preventive measures', 'Criminal Law'),
  ('LBN-CRIM-001', '227-230', 'Causes d''exemption de peine - Contrainte et état de nécessité', 'fr', 'Penal Code, Article 227-230', 'Grounds for exemption', 'Criminal Law'),
  ('LBN-CRIM-001', '227-230', 'أسباب الإعفاء من العقاب - الإكراه والضرورة', 'ar', 'Penal Code, Article 227-230', 'Grounds for exemption', 'Criminal Law'),
  ('LBN-CRIM-001', '231-232', 'Folie - Absence de responsabilité et responsabilité atténuée', 'fr', 'Penal Code, Article 231-232', 'Insanity defense', 'Criminal Law'),
  ('LBN-CRIM-001', '231-232', 'الجنون - عدم المسؤولية والمسؤولية المخففة', 'ar', 'Penal Code, Article 231-232', 'Insanity defense', 'Criminal Law'),
  ('LBN-CRIM-001', '235-236', 'Ivresse et intoxication - Effet sur la responsabilité pénale', 'fr', 'Penal Code, Article 235-236', 'Intoxication', 'Criminal Law'),
  ('LBN-CRIM-001', '235-236', 'السكر والتخدير - أثره على المسؤولية الجزائية', 'ar', 'Penal Code, Article 235-236', 'Intoxication', 'Criminal Law'),
  ('LBN-CRIM-001', '240', 'Aux fins du présent Code, l''enfant est celui âgé de 7 à 12 ans, l''adolescent de 12 à 15 ans, le mineur de 15 à 18 ans', 'fr', 'Penal Code, Article 240', 'Age definitions', 'Criminal Law'),
  ('LBN-CRIM-001', '240', 'لأغراض هذا القانون، الطفل هو من بلغ سبع سنين حتى اثنتي عشرة سنة، والحدث من اثنتي عشرة حتى الخامسة عشرة، والقاصر من الخامسة عشرة حتى الثامنة عشرة', 'ar', 'Penal Code, Article 240', 'Age definitions', 'Criminal Law'),
  ('LBN-CRIM-001', '249-250', 'Causes d''excuse prévues par la loi', 'fr', 'Penal Code, Article 249-250', 'Statutory grounds for exemption', 'Criminal Law'),
  ('LBN-CRIM-001', '249-250', 'أسباب العذر المنصوص عليها قانوناً', 'ar', 'Penal Code, Article 249-250', 'Statutory grounds for exemption', 'Criminal Law'),
  ('LBN-CRIM-001', '251', 'Causes d''atténuation de la peine', 'fr', 'Penal Code, Article 251', 'Mitigation of penalty', 'Criminal Law'),
  ('LBN-CRIM-001', '251', 'أسباب تخفيف العقاب', 'ar', 'Penal Code, Article 251', 'Mitigation of penalty', 'Criminal Law'),
  ('LBN-CRIM-001', '257', 'Causes d''aggravation de la peine', 'fr', 'Penal Code, Article 257', 'Aggravation of penalty', 'Criminal Law'),
  ('LBN-CRIM-001', '257', 'أسباب تشديد العقاب', 'ar', 'Penal Code, Article 257', 'Aggravation of penalty', 'Criminal Law'),
  ('LBN-CRIM-001', '262-265', 'Habitualité de la criminalité - Le délinquant habituel', 'fr', 'Penal Code, Article 262-265', 'Persistent offending', 'Criminal Law'),
  ('LBN-CRIM-001', '262-265', 'اعتياد الإجرام - المجرم المحترف', 'ar', 'Penal Code, Article 262-265', 'Persistent offending', 'Criminal Law'),
  ('LBN-CRIM-001', '351-358', 'Crimes de corruption, détournement et faux', 'fr', 'Penal Code, Article 351-358', 'Corruption offenses', 'Criminal Law'),
  ('LBN-CRIM-001', '351-358', 'جرائم الرشوة والاختلاس والتزوير', 'ar', 'Penal Code, Article 351-358', 'Corruption offenses', 'Criminal Law'),
  ('LBN-CRIM-001', '367', 'Détention arbitraire - Atteinte à la liberté personnelle', 'fr', 'Penal Code, Article 367', 'Arbitrary detention', 'Criminal Law'),
  ('LBN-CRIM-001', '367', 'الحجر التعسفي - الاعتداء على الحرية الشخصية', 'ar', 'Penal Code, Article 367', 'Arbitrary detention', 'Criminal Law'),
  ('LBN-CRIM-001', '491-500', 'Avortement et blessures', 'fr', 'Penal Code, Article 491-500', 'Abortion and injuries', 'Criminal Law'),
  ('LBN-CRIM-001', '491-500', 'الإجهاض والإيذاء', 'ar', 'Penal Code, Article 491-500', 'Abortion and injuries', 'Criminal Law'),
  ('LBN-CRIM-001', '500 bis', 'Abandon d''un mineur - Traite d''enfants', 'fr', 'Penal Code, Article 500 bis', 'Child abandonment and trafficking', 'Criminal Law'),
  ('LBN-CRIM-001', '500 bis', 'التخلي عن قاصر - الاتجار بالأطفال', 'ar', 'Penal Code, Article 500 bis', 'Child abandonment and trafficking', 'Criminal Law'),
  ('LBN-CRIM-001', '553-557', 'Homicide, blessures et coups', 'fr', 'Penal Code, Article 553-557', 'Homicide and assault', 'Criminal Law'),
  ('LBN-CRIM-001', '553-557', 'القتل والإيذاء والضرب', 'ar', 'Penal Code, Article 553-557', 'Homicide and assault', 'Criminal Law'),
  ('LBN-CRIM-001', '273-278', 'Trahison et espionnage', 'fr', 'Penal Code, Article 273-278', 'Treason and espionage', 'Criminal Law'),
  ('LBN-CRIM-001', '273-278', 'الخيانة والتجسس', 'ar', 'Penal Code, Article 273-278', 'Treason and espionage', 'Criminal Law'),
  ('LBN-CRIM-001', '281-289', 'Espionnage - Crimes contre la sûreté de l''État', 'fr', 'Penal Code, Article 281-289', 'Espionage', 'Criminal Law'),
  ('LBN-CRIM-001', '281-289', 'التجسس - جرائم ضد أمن الدولة', 'ar', 'Penal Code, Article 281-289', 'Espionage', 'Criminal Law'),
  ('LBN-CRIM-001', NULL, 'The Lebanese Penal Code was enacted on March 1, 1943, by Legislative Decree No. 340, shortly before Lebanon''s independence. It replaced the Ottoman Penal Code and was heavily influenced by French criminal law. The Code has been amended numerous times, particularly regarding penalties, corruption offenses, and crimes against children.', 'en', 'Penal Code — Historical Context', 'Historical context and overview', 'Criminal Law'),
  ('LBN-CRIM-002', '1-10', 'Dispositions générales', 'fr', 'Code of Criminal Procedure, Article 1-10', 'General provisions', 'Procedure'),
  ('LBN-CRIM-002', '1-10', 'أحكام عامة', 'ar', 'Code of Criminal Procedure, Article 1-10', 'General provisions', 'Procedure'),
  ('LBN-CRIM-002', '11-37', 'Parquet - Compétences et pouvoirs', 'fr', 'Code of Criminal Procedure, Article 11-37', 'Public Prosecution', 'Procedure');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LBN-CRIM-002', '11-37', 'النيابة العامة - اختصاصاتها وصلاحياتها', 'ar', 'Code of Criminal Procedure, Article 11-37', 'Public Prosecution', 'Procedure'),
